/***********************************************************************
 * AppPageControl: PromptFilter 
 */
 IG$.ctrlPromptFilter = IG$.extend(IG$.ctrlBase, {
	type: "filter",
	initComponent: function() {
		var me = this;
		me.activeIndex = 0;
		me.p.push(
			{name: "flexHeight", type: "property", datatype: "number", value: 0},
			{name: "minHeight", type: "property", datatype: "number", value: 0},
			{name: "request_run", type: "event"}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},
	
	processEvent: function(evttype, obj) {
	},

	invalidate: function () {
		var me = this;
	},
	
	initDrawing: function () {
		var me = this,
			mcontainer = $("<div></div>").appendTo(me.html),
			cbtn;

		if (!me.viewer)
		{
			me.sop = new IG$.sheetfiltercomp(me.layout._xparam);
			me.sop.objtype = "FILTER";
			me.viewer = new IG$.dynFilterView(me.instance, mcontainer, me.sop, null, 1);
			me.viewer.callback = new IG$.callBackObj(me, function() {
				me.html.trigger("e_request_run");
			});
		}
		
		if (me.dsmode)
		{
			cbtn = $("<div class='igc-p-config'><div class='igc-p-config-bg'></div><button>Config</button></div>").appendTo(me.html);
			$("button", cbtn).bind("click", function() {
				me.configSheet();
			});
		}
		
		me.tl$.hide();
		me.__pcinit();
	},

	configSheet: function() {
		var me = this,
			pop = new IG$.sheetobj({
				instance: me.instance,
				sheetoption: me.viewer.sheetoption, 
				reportoption: null,
				createMode: 1,
				callback: new IG$.callBackObj(me, function(dlg, sheetview) {
					var tvalue = me.sop.getXML();

					me.layout._xparam = IG$.loadXML(tvalue);
					me.viewer.validateItems();
				}, me.viewer)
			});
		
		IG$.checkLogin(this, pop);
	},
	updateProperty: function(kname, value) {
		var me = this;
		
		if (me.dsmode)
		{
			return;
		}
		
		switch(kname)
		{
		case "report_control":
			break;
		}
	},

	updateLayout: function() {
		var me = this,
			dashboard = me.ctrl.dashboard;
	},

	getSelectionData: function(param) {
		var me = this,
			filteritems,
			i, j,
			viewer = me.viewer,
			berr = [],
			fitem,
			bs,
			rval = [];

		if (param && param.name && viewer)
		{
			filteritems = viewer.sheetoption.model.filter_items;

			if (filteritems && filteritems.length)
			{
				for (i=0; i < filteritems.length; i++)
				{
					if (filteritems[i].name == param.name)
					{
						fitem = filteritems[i];
						break;
					}
				}

				if (fitem)
				{
					bs = viewer.checkFilterValuesItem(fitem, berr, true);

					if (bs)
					{
						for (j=0; j < fitem.value.length; j++)
						{
							rval.push(fitem.value[j]);
						}
					}
				}
			}
		}

		return rval;
	}
});

IG$.controls.promptfilter = new IG$.ctrlPromptFilter({}, null);