

/**
 * textarea control
 */
IG$._FC_textarea = $s.extend(IG$._baseFC, {
	objtype: "textarea",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	properties: [
		{name: "text", type: "string"},
		{name: "placeholder", type: "string"}
	],
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			rangevalue = fmodel.rangevalue,
			rangelabel = me.rangelabel,
			_init_value = fmodel._init_value || fmodel.initial_values,
			ui = $("<div class='idv-sel-combo'></div>").appendTo(container),
			m1;
						
		m1 = $("<div class='idv-sel-flow-full'><textarea name='c_m1'></textarea></div>").appendTo(ui);
		
		if (_init_value && _init_value.length)
		{
			$("[name=c_m1]", m1).val(me.getDefaultValue(fitem, 0));
			me.trigger("change_val");
		}
		return ui;
	},
	updateValue: function(value) {
		var me = this,
			ui = me.ui;
			
		var tval = $("[name=c_m1]", ui).val();
		
		if (tval)
		{
			value.push({code: tval, value: tval});
		}
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			ui = me.ui,
			sctrl1;
		sctrl1 = $("[name=c_m1]", ui);
		sctrl1.val(values[0]);
	},
	clear: function(trigger) {
		var me = this,
			ui = me.ui;
		$("[name=c_m1]", ui).val("");
		me.trigger("change_val");
	},
	
	$setProp: function(fitem, key, value) {
		var me = this,
			ui = me.ui,
			sctrl1;
			
		sctrl1 = $("[name=c_m1]", ui);
			
		switch(key)
		{
		case "placeholder":
			sctrl1.attr("placeholder", value);
			break;
		case "text":
			me.setValue([value]);
			break;
		}
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["textarea"] = new IG$._FC_textarea();