IG$.n$brwSch = $s.extend($s.panel, {
	layout: "border",
	owner: null,
	
	reqSearch: function() {
		var keyword = this.down("[name=keyword]").getValue(),
			fltsetdate = this.down("[name=fltsetdate]").getValue(),
			fltfromdate = this.down("[name=fltfromdate]").getRawValue().split("-"),
			flttodate = this.down("[name=flttodate]").getRawValue().split("-"),
			fltypegrid = this.down("[name=fltypegrid]"),
			i,
			typelist = [],
			panel=this,
			req = new IG$._rpc$(),
			soption,
			enablesearch = false;
		
		for (i=0; i < fltypegrid.store.data.items.length; i++)
		{
			if (fltypegrid.store.data.items[i].get("selected") == true)
			{
				typelist.push(fltypegrid.store.data.items[i].get("type"));
			}
		}
		
		if ((keyword && keyword.length > 0) || 
			(fltsetdate == true)) // || (itemlist != null && itemlist.length > 0))
		{
			enablesearch = true;
		}
		
		if (enablesearch == true)
		{
			soption = {option: "search", name: keyword};
			if (fltsetdate == true)
			{
				soption.fromdate = fltfromdate.join("") + "000000";
				soption.todate = flttodate.join("") + "240000";
			}
			
			if (typelist && typelist.length > 0)
			{
				soption.typelist = typelist.join(";");
			}
			
			req.init(panel, 
				{
					ack: "helpcontent",
					payload: {},
					mbody: soption
				}, panel, panel.rs_reqSearch, null);
			req.send();
		}
	},
	
	rs_reqSearch: function(xdoc) {
		var panel = this,
			i,
			cnode = IG$.XGetNode(xdoc, "/smsg/result"),
			cnodes,
			mgrid = panel.down("[name=mgrid]"),
			data = [], d;
		
		if (cnode)
		{
			cnodes = IG$.XGetChildNodes(cnode);
			for (i=0; i < cnodes.length; i++)
			{
				d = IG$.XGetAttrProp(cnodes[i]);
				d.iconCls = IG$.get_metatype_icon(d.type.toLowerCase(), d);
				data.push(d);
			}
		}
		mgrid.store.loadData(data);
	},
	
	initComponent: function() {
		var resultTpl = Ext.create("Ext.XTemplate",
			'<tpl for=".">',
			'<div class="idv-sch-item">',
				'<div class="idv-sch-icon {iconCls}"> </div><h3><span>{name}</span>&nbsp;</h3>',
				'<p>{nodepath}</p>',
			'</div></tpl>',
		{
			formatDate: function(value)
			{
				return Ext.Date.format(value, "M j, Y");
			}
		});
		
		var items = [
			{
				xtype: "panel",
				layout: "anchor",
				autoHeight: true,
				defaults: {
					anchor: "100%"
				},
				region: "north",
				items: [
					{
						xtype: "textfield",
						fieldLabel: IRm$.r1("B_KEYWORD"), // Keyword",
						labelWidth: 50,
						border: false,
						flex: 1,
						height: 20,
						hideLabel: false,
						
						name: "keyword",
						value: "",
						allowBlank: true,
						blankText: IRm$.r1("B_REQ"),
						enableKeyEvents: true,
						listeners: {
							keyup: function(item, e) {
								if (e.keyCode == 13)
								{
									this.reqSearch();
								}
							},
							scope: this
						}
					},
					{
						xtype: "fieldset",
						title: IRm$.r1("L_ADV_OPTION"), // "Advanced Option",
						collapsible: true,
						autoHeight: true,
						collapsed: true,
						defaults: {
							labelWidth: 80,
							anchor: "100%",
							layout: "anchor",
							defaults: {
								anchor: "100%"
							}
						},
						items: [
							{
								xtype: "combobox",
								name: "fltypegroup",
								labelField: "Type",
								queryMode: "local",
								displayField: "name",
								valueField: "gcode",
								
								editable: false,
								
								store: {
									fields: [
										 "name", "gcode"
									 ],
									 data: [
										 {name: "----- Quick Select -----", gcode: ""},
										 {name: IRm$.r1("B_ALL"), gcode: "all"},
										 {name: "Folder and Workspace", gcode: "folder"},
										 {name: (IG$.level == 1) ? "Report or dashboard" : "Report", gcode: "report"},
										 {name: "Analysis item", gcode: "dimensions"}
									 ]
								},
								listeners: {
									select: function(combo, records, eOpts) {
										var selvalue = combo.getValue(),
											fltypegrid = this.down("[name=fltypegrid]"),
											store = fltypegrid.store,
											i,
											mtype,
											mkey = null,
											regex = null;
										
										switch (selvalue)
										{
										case "all":
											mkey = null;
											break;
										case "report":
											mkey = "Report|Dashboard";
											break;
										case "folder":
											mkey = "Folder";
											break;
										case "dimensions":
											mkey = "Dimension|Measure";
											break;
										}
										
										if (mkey != null)
										{
											regex = new RegExp(mkey);
										}
										
										for (i=0; i < store.data.items.length; i++)
										{
											mtype = store.data.items[i].get("type");
											if (mkey == null || (regex != null && regex.test(mtype) == true))
											{
												store.data.items[i].set("selected", true);
											}
											else
											{
												store.data.items[i].set("selected", false);
											}
										}
									},
									afterrender: function(ui) {
										ui.setValue("");
									},
									scope: this
								}
							},
							{
								xtype: "gridpanel",
								name: "fltypegrid",
								region: "center",
								layout: "fit",
								hideHeaders: true,
								flex: 1,
								height: 100,
								scroll: "vertical",
								stateful: false,
								store: {
									fields: [
										"selected", "name", "type", "nodepath", "uid", "iconimg"
									],
									data: [
										{name: "Folder", type: "Folder"},
										{name: "Cube", type: "Cube"},
										{name: "Report", type: "Report"},
										// ((IG$.level == 1) ? {name: "Dashboard", type: "Dashboard"},
										{name: "Dimension", type: "Dimension"},
										{name: "Measure", type: "Measure"}
									]
								},
								
								// stateful: true,
								
								columns: [
									{
										xtype: "checkcolumn",
										dataIndex: "selected",
										width: 30,
										editor: {
											xtype: "checkbox",
											cls: "x-grid-checkheader-editor"
										}
									},
									{	 
										header: "",  
										dataIndex: "iconimg",
										sortable: false,
										hideable: false,
										width: 20
									},
									{ 
										header: IRm$.r1("B_NAME"),  
										dataIndex: "name",
										sortable: false,
										hideable: false,
										flex: 1
									}
								],
								listeners: {
									afterrender: function(ui) {
									}
								}
							},
							{
								xtype: "checkbox",
								name: "fltsetdate",
								fieldLabel: "",
								boxLabel: IRm$.r1("L_SET_DATE"), // "Set date",
								listeners: {
									change: function(field, newvalue, oldvalue, eOpt) {
										var checked = field.getValue(),
											fltfromdate = this.down("[name=fltfromdate]"),
											flttodate = this.down("[name=flttodate]");
										
										fltfromdate.setVisible(checked);
										flttodate.setVisible(checked);
									},
									scope: this
								}
							},
							{
								xtype: "datefield",
								name: "fltfromdate",
								hidden: true,
								labelWidth: 70,
								fieldLabel: IRm$.r1("B_FROM"), // From",
								maxValue: new Date(),
								format: "Y-m-d",
								value: new Date()
							},
							{
								xtype: "datefield",
								name: "flttodate",
								hidden: true,
								labelWidth: 70,
								fieldLabel: IRm$.r1("B_TO"), // To",
								maxValue: new Date(),
								format: "Y-m-d",
								value: new Date()
							}
						],
						listeners: {
							
						}
					},
					{
						xtype: "button",
						text: IRm$.r1("B_SEARCH"),
						border: false,
						handler: function() {
							this.reqSearch();
						},
						scope: this
					}
				]
			},
			{
				xtype: "gridpanel",
				name: "mgrid",
				region: "center",
				flex: 1,
				store: {
					fields: [
						{name: "name"},
						{name: "type"},
						{name: "nodepath"},
						{name: "uid"},
						{name: "iconimg"}
					]
				},
				stateful: true,
				/*
				columns: [
					{	 header: "",  
						dataIndex: "iconimg",
						sortable: false,
						hideable: false,
						width: 20
					},
					{ 
						header: IRm$.r1("B_NAME"),  
						dataIndex: "name",
						sortable: false,
						hideable: false,
						flex: 1
					},
					{ 
						header: IRm$.r1("B_PATH"), 
						dataIndex: "nodepath", 
						flex: 1,
						sortable: false,
						hideable: false
					}
				],
				*/
				xtype: "dataview",
				loadMask: false,
				autoScroll: true,
				tpl: resultTpl,
				itemSelector: "div.idv-sch-item",
				listeners: {
					itemdblclick: function(view, record, item, index, ev) {
						var dt = record.data;
					
						if (dt)
						{
							this.owner.navigateTree(dt);
						}
					},
					scope: this
				}
			}
		];
		
		$s.apply(this, {
			items: items
		});
		IG$.n$brwSch.superclass.initComponent.call(this);
	}
});