/***********************************************************************
 * AppPageControl: TextInput 
 */

IG$.ctrlTextInput = IG$.extend(IG$.ctrlBase, {
	type: "textbox",

	initComponent: function() {
		var me = this,
			dsmode = me.dsmode,
			div, dnode,
			htmltext,
			mask_enum = IG$._txtinpMaskOptEnum,
			mask_pattern = IG$._txtinpMaskOpt;

		if (!mask_enum)
		{
			mask_enum = IG$._txtinpMaskOptEnum = [];

			$.each(mask_pattern, function(k, v) {
				mask_enum.push({name: k, value: k});
			});
		}
		
		me.p.push(
			{name: "disabled", type: "property", datatype: "boolean", value: false},
			{name: "fieldlabel", type: "property", datatype: "string"},
			/*
			{name: "labelwidth", type: "property", datatype: "number", value: 80},
			{name: "labelposition", type: "property", datatype: "string", value: "left", 
				"enum": [
					{name: "top", value: "top"},
					{name: "left", value: "left"}
				]
			},
			{name: "labelalign", type: "property", datatype: "string", value: "left", 
				"enum": [
					{name: "right", value: "right"},
					{name: "left", value: "left"},
					{name: "center", value: "center"}
				]
			},
			*/
			{name: "inputtype", type: "property", datatype: "string", value: "text",
				"enum": [
					{name: "text", value: "text"},
					{name: "password", value: "password"},
					{name: "number", value: "number"},
					{name: "email", value: "email"},
					{name: "tel", value: "tel"},
					{name: "url", value: "url"}
				]
			},
			{name: "maxlength", type:"property", datatype: "number", value: 0},
			{name: "mask", type: "property", datatype: "string", enum: mask_enum},
			{name: "placeholder", type: "property", datatype: "string"},
			{name: "readOnly", type: "property", datatype: "boolean", value: false},
			{name: "show_counter", type:"property", datatype: "boolean", value: 0},
			{name: "text", type: "property", datatype: "string"},

			{name: "prefix", type: "property", datatype: "string"},
			{name: "suffix", type: "property", datatype: "string"},

			{name: "enterkey", type: "event"}
		)
		
		me.superclass.prototype.initComponent.call(me);
	},

	updateProperty: function(kname, value) {
		var me = this,
			mp$dv = me.mp$dv,
			mp$ = me.mp$;
		
		switch (kname)
		{
		case "text":
			mp$.value = value;
			break;
		case "labelwidth":
			me.tl$.width(value);
			break;
		case "labelposition":
			// cmp$.$define("labelPosition", value);
			break;
		case "inputtype":
			mp$.type = value;
			$("input", mp$dv).attr("type", value);
			break;
		case "maxlength":
			if (value)
			{
				mp$.maxLength = value;
			}
			else
			{
				mp$.maxLength = -1;
			}
			break;
		case "show_counter":
			// cmp$.attr("data-mdb-showcounter", value ? "true" : "false");
			break;
		case "mask":
			var m = IG$._txtinpMaskOpt[value];
			if (m)
			{
				var opt = m.option;
				mp$.pattern = m.mask; // , opt);
			}
			else
			{
				mp$.pattern = '';
			}
			break;
		case "labelalign":
			// cmp$.$define("labelAlign", value);
			break;
		case "placeholder":
			value = value && value.substring(0, 2) == "L_" ? IRm$.r1(value) : value;
			mp$.placeholder = value;
			break;
		case "disabled":
			mp$.disabled = value;
			break;
		case "readOnly":
			mp$.readOnly = value;
			break;
		case "prefix":
			mp$.prefixText = value || "";
			break;
		case "suffix":
			mp$.suffixText = value || "";
			break;
		}
	},
	
	initDrawing: function () {
		var me = this,
			actionlist = me.ctrl.actionlist,
			property = me.property,
			owner = me.ctrl.owner,
			cmp$,
			lbl$,
			fid = me._get_id();

		me.el$.addClass("form-outline");
		me.tl$ && me.tl$.hide();
		me.mp$dv = me.createTextField(me.el$, me.property.fieldlabel);
		lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$dv);
		cmp$ = me.cmp$ = $("input", me.mp$dv);
		me.mp$ = mdc.textField.MDCTextField.attachTo(me.mp$dv);
		// cmp$.addClass("is-invalid");
		cmp$ && cmp$.bind({
			focus: function(ev) {
				var m = this;

				setTimeout(function() {
					m.select();
				}, 10)
			},
			keyup: function(ev) {
				if (ev.keyCode == 13 && actionlist["enterkey"])
				{
					me.triggerEvent("enterkey", {
						ctrl: me.ctrl,
						ptr: me,
						event: "enterkey"
					});
				}
			}
		});

		me.btn = $("<button class='ig-db-button'>..</button>")
			.hide()
			.appendTo(me.el$);

		if (me.applicationItem)
		{
			me.btn.show();
		}

		me.btn.bind({
			click: function(ev) {
				ev.stopPropagation();
				ev.preventDefault();

				hfilter = owner.checkHFilter(me);
					
				if (hfilter == false)
					return;
				
				var dlg = new IG$.dynFilter({
					instance: me.instance,
					selModel: {
						mode: "SINGLE",
						selType: "checkboxmodel",
						checkSelector: ".x-grid-cell"
					},
					smode: property.selectionMode,
					callback: new IG$.callBackObj(me, function(sel) {
						var me = this,
							i, tvalue = "",
							fsel, sel_i;
							
						fsel = [];
						me.clearInvalid();
						if (sel && sel.length)
						{
							for (i=0; i < sel.length; i++)
							{
								if (sel.items)
								{
									sel_i = sel.items[i];
									fsel.push({
										code: sel_i.get("code"),
										value: sel_i.get("disp")
									});
								}
								else
								{
									sel_i = sel[i];
									fsel.push({
										code: sel_i.code,
										value: sel_i.value
									});
								}
							}
						}
						
						if (fsel.length)
						{
							me.selection = fsel;
							tvalue = (fsel[0].value || fsel[0].code) + (fsel.length > 1 ? "(" + (fsel.length-1) + " more)" : "");
						}
						else
						{
							me.selection = null;
						}
						
						if (property.isnecessary)
						{
							(!fsel || (fsel && !fsel.length)) && me.markInvalid("required");
						}
						
						me.mp$.value = tvalue;
						me.trigger("enterkey");
					}),
					reqItem: me.applicationItem,
					reqView: me,
					hfilter: hfilter
				});
				IG$.checkLogin(owner, dlg);
			}
		});
		
		me.superclass.prototype.initDrawing.call(me);
	},
	
	commit: function() {
		var me = this;
		me.property.text = me.mp$.value;
	},
	
	invalidate: function () {
	},
	
	getSelectionData: function(itemname) {
		var me = this,
			value = me.mp$.value || "",
			property = me.property,
			mask_pattern = IG$._txtinpMaskOpt,
			mask = property.mask;

		if (mask && mask_pattern[mask] && mask_pattern[mask].formatter)
		{
			value = mask_pattern[mask].formatter.apply(me, [value]);
		}

		return me.selection || (value ? [{code: value, value: value}] : null);
	}
});

IG$._txtinpMaskOpt = {
	date: {name: "date", mask: "0000-00-00"},
	time: {name: "time", mask: "00:00:00"},
	date_time: {name: "date_time", mask: "0000-00-00 00:00:00"},
	phone: {
		name: "phone", 
		mask: "(00)0000-0000", 
		formatter: function(value) {
			if (value)
			{
				value = value.replace("(", "");
				value = value.replace(")", "");
				value = value.replace("-", "");
			}
			return value;
		}
	},
	phone_us: {
		name: "phone_us", 
		mask: "(000)0000-0000", 
		formatter: function(value) {
			if (value)
			{
				value = value.replace("(", "");
				value = value.replace(")", "");
				value = value.replace("-", "");
			}
			return value;
		}
	},
	money: {
		name: "money", 
		mask: "#,##0", 
		option: {reverse: true}, 
		formatter: function(value) {
			if (value)
			{
				value = value.split(",").join("");
			}
			return value;
		}
	},
	ip_address: {name: "ip addrese", mask: "0ZZ.0ZZ.0ZZ.0ZZ", option: {
		translation: {
			"Z": {
				pattern: /[0-9]/,
				optional: true
			}
		}
	}},
	percent: {
		name: "percent", 
		mask: "##0.00%", 
		option: {reverse: true},
		formatter: function(value) {
			if (value)
			{
				value = value.replace("%", "");
				value = value.split(",").join("");
			}
			return value;
		}
	},
	ssn: {name: "ssn", mask: "000r00r0000", option: {
		translation: {
			"r": {
				pattern: /[-]/,
				fallback: "-"
			},
			placeholder: "___-__-____"
		}
	}},
	ssn2: {name: "ssn2", mask: "000-00-0000", option: {placeholder: "__-__-____"}}
};

IG$.controls.textbox = new IG$.ctrlTextInput({}, null);