IG$.cVis.bubblemap = $s.extend(IG$.cVis.base, {
	subtype: "bubblemap",

	draw: function(mresult) {
		var i,
			j,
			me = this,
			cop = me.chart_option,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			c,
			r,
			nval = 0,
			me = this,
			xs = [], ys = [], bubbledata = [],
			xmap = {}, ymap = {}, axisx = [], axisy = [], xinc=0, yinc=0,
			bmaprow = cop.bmaprow,
			bmapyaxis = cop.bmapyaxis,
			isbmapyaxis,
			sep = me.getSep();

		me.drawmode = "bubblemap";

		if (bmapyaxis == false && fc == 2)
		{
			isbmapyaxis = false;
			for (i=fr; i < data.length; i++)
			{
				if (data[i].length > fc)
				{
					nval = Number(data[i][fc].code) || 0;
					nval = (nval < 0) ? 0 : nval;
				}
				
				if (nval > 0)
				{
					bubbledata.push(nval);
					
					for (j=0; j < fc; j++)
					{
						c = data[i][j];
						tn = c.text || c.code;
						if (j == 0)
						{
							if (!xmap[tn])
							{
								xmap[tn] = {
									inc: xinc++
								};
								axisx.push(tn);
							}
							xs.push(xmap[tn].inc);
						}
						else if (j == 1)
						{
							if (!ymap[tn])
							{
								ymap[tn] = {
									inc: yinc++
								};
								axisy.push(tn);
							}
							ys.push(ymap[tn].inc);
						}
					}
				}
			}
		}
		else
		{
			isbmapyaxis = true;
			var rowval;
			for (i=0; i < fr; i++)
			{
				for (j=fc; j < data[i].length; j++)
				{
					c = data[i][j];
					tn = c.text || c.code;
					if (i == 0)
					{
						axisy.push(tn);
					}
					else
					{
						axisy[j-fc] += sep + tn;
					}
				}
			}

			for (i=fr; i < data.length; i++)
			{
				rowval = "";
				for (j=0; j < data[i].length; j++)
				{
					c = data[i][j];
					tn = c.text || c.code;
					if (j < fc)
					{
						rowval = (j == 0) ? tn : rowval + sep + tn;
					}
					else
					{
						if (j == fc)
						{
							axisx.push(rowval);
						}
						xs.push(i-fr);
						ys.push(j - fc);

						nval = Number(tn) || 0;
						nval = (nval < 0) ? 0 : nval;
						bubbledata.push(nval);
					}
				}
			}
		}

		r = me.bmap = Raphael(me.container);

		var jdom = $(me.container),
			w = IG$.j$ext._w(jdom),
			h = IG$.j$ext._h(jdom);
			
		if (bubbledata.length)
		{
			r.dotchart(0, 0, w, h, xs, ys, bubbledata, {
				symbol: "o",
				max: cop.bmapsize,
				heat: true,
				axis: "0 0 1 1",
				axisxstep: Math.min(axisx.length-1, 20),
				axisystep: Math.min(axisy.length-1, 20),
				axisxlabels: axisx,
				axisxtype: " ",
				axisytype: " ",
				axisylabels: axisy
			}).hover(function () {
				this.marker = this.marker || r.tag(this.x, this.y,
					axisx[this.X] + "\n" + axisy[this.Y] + "\n" + this.value
				, 0, this.r + 2).insertBefore(this);
				this.marker.show();
			}, function () {
				this.marker && this.marker.hide();
			}).click(function() {
				var sender = null,
					param = null;
	
				if (isbmapyaxis == false)
				{
					sender = {
						name: axisx[this.X] + sep + axisy[this.Y]
					},
					param = {
						point: {
							category: this.value
						}
					};
				}
				else
				{
					sender = {
						name: axisx[this.X]
					},
					param = {
						point: {
							category: axisy[this.Y]
						}
					};
				}
	
				(sender && param) &&
				me.procClickEvent(sender, param);
			});
		}
	},

	updatedisplay: function(w, h) {
		var me = this;
		me.$mresult && me.draw(me.$mresult);
	},

	getExportData: function(pobj, callback) {
		if (me.bmap)
		{
			svg = me.bmap.toSVG.call(me.bmap);
			pobj.image_type = "svg";
			pobj.image_data = Base64.encode(svg);
		}
		callback.execute(pobj);
	}
});