/***********************************************************************
 * AppPageControl: Button 
 */
 IG$.ctrlButton = IG$.extend(IG$.ctrlBase, {
	type: "button",
	initComponent: function() {
		var me = this,
			btn_types = [
				{name: "none", value: ""},
				{name: "Filled", value: "mdc-button--raised"},
				{name: "Outlined", value: "mdc-button--outlined"},
				{name: "Text", value: "mdc-button"}
			];
		
		me.btn_types = btn_types;
		me.btn_type_names = {};
		for (var k of btn_types) {
			me.btn_type_names[k.value] = 1;
		}
		me.p.push(
			{name: "label", type: "property", datatype: "string"},
			{name: "click", type: "event"},
			{name: "btn_type", type: "property", datatype: "string", value: "primary",
				"enum": btn_types
			}
		);
		
		me.superclass.prototype.initComponent.call(me);
	},

	updateProperty: function(kname, value) {
		var me = this,
			cmp$ = me.cmp$;

		if (!cmp$)
		{
			me._render();
			return;
		}
		
		switch (kname)
		{
		case "label":
			$(".mdc-button__label", cmp$[0]).html(value);
			// cmp$[0].renderRoot.querySelector(".label").innerHTML = value;
			break;
		case "btn_type":
			me._render();
			break;
		}
	},

	initDrawing: function () {
		var me = this,
			dsmode = me.dsmode,
			property = me.property,
			actionlist = me.ctrl.actionlist,
			pdb = me.ctrl.parentcontrol;

		me._render();

		me.el$.addClass("form-outline");
		
		me.__pcinit();
		me.tl$.hide();

		me.superclass.prototype.initDrawing.call(me);
	},

	_render: function() {
		var me = this;
		me._render_timer && clearTimeout(me._render_timer);
		me._render_timer = setTimeout(function() {
			me._render_int();
		}, 10);
	},

	_render_int: function() {
		var me = this,
			dsmode = me.dsmode,
			property = me.property,
			actionlist = me.ctrl.actionlist,
			pdb = me.ctrl.parentcontrol;

		if (!me.btn_type_names[property.btn_type])
		{
			property.btn_type = "";
		}

		property.btn_type = property.btn_type || "md-text-button";

		if (!me.cmp$ || (me.$btn_type != property.btn_type))
		{
			if (me.cmp$)
			{
				me.cmp$.remove();
			}

			me.$btn_type = property.btn_type;

			me.cmp$ = $("<button class='mdc-button " + me.$btn_type + " igc-md-btn' style=\"width:100%\"><span class='mdc-button__ripple'></span><span class='mdc-button__focus-ring'></span><span class='mdc-button__label'>" + (property.label || "") + "</span></button>").appendTo(me.el$);
			mdc.iconButton.MDCIconButtonToggle.attachTo(me.cmp$[0]);

			me.cmp$.bind({
				click: function(e) {
					me.triggerEvent("click", {
						ctrl: me.ctrl,
						ptr: me,
						event: "click"
					});
				}
			});	
		}
	},
	
	invalidate: function () {
	}
});

IG$.controls.button = new IG$.ctrlButton({}, null);