IG$.dockingWidget = function(owner, docid, config) {
	var me = this,
		btnarea;
	
	me.owner = owner;
	me.container = false;
	me.showtitle = true;
	me._v = true;
	me.visible = true;
	
	me.x = (config && config.x) ? config.x : null;
	me.y = (config && config.y) ? config.y : null;
	me.width = (config && config.width) ? config.width : null;
	me.height = (config && config.height) ? config.height : null;
	me.fixed_width = false;
	me.fixed_height = false;
	me.hidetitle = false;
	// me.playout = "V";

	me.docid = docid;
	me.activeTab = 0;
	me.dragging = false;
	
	me.box = $("<div class='idv-dk-main' " + docid + "></div>").css({
		position: "absolute",
		width: (IG$.j$ext._w(owner.box) || 100), 
		height: (IG$.j$ext._h(owner.box) || 100)
	}); // .dselect();
	
	me.binner = $("<div class='dock_inner'></div>").appendTo(me.box); // .dselect();
	me.bcollapse = $("<div class='dock_collpase_indicator'></div>").appendTo(me.box).hide();
	
	me.box_title = $("<div class='dock_title doc_title_normal'></div>").appendTo(me.binner).dselect();
	me.box_container = $("<div class='dock_content'></div>").appendTo(me.binner);
	
	/*
	$("<span class='dock_title_fbutton'></span>").appendTo(me.box_title).bind("click", function(e) {
		me.box_slideout = !me.box_slideout;
		// me.updTitleFloat();
	});
	*/
	
	$("<div class='dock_title_icon'></div>").appendTo(me.box_title);
	$("<div class='dock_title_text'><div id='dock_title_text'>&nbsp;</div></div>").appendTo(me.box_title);

	$("#dock_title_text", me.box_title).bind("click", function(e) {
		$(this).focus();
	});

	// keyup, input
	$("#dock_title_text", me.box_title).bind({
		"blur paste": function(e) {
			const $this = $(this),
				p = me.owner;

			var nvalue = $this.html();
			
			nvalue = nvalue.split("&nbsp;").join(" ");

			if (me.title != nvalue)
			{
				me.box.trigger("title_changed", {
					panel: me,
					title: nvalue
				});
				
				p && p.configDock.call(p, me.docid, "config_pivot");
			}
		},
		"keydown": function(e) {
			if (e.keyCode == 13)
			{
				e.preventDefault();
				e.stopImmediatePropagation();

				$(this).blur();
			}
		}
	});

	me.btnarea = btnarea = $("<div class='dock_title_btnarea'></div>").appendTo(me.box_title);
	
	me.measure_selector = $("<select class='dock_measure_selector'></select>").appendTo(me.box_title);
	
	me.measure_selector.bind("change", function(e) {
		var val = me.measure_selector.val(),
			i,
			sval = -1;
		
		if (val && me._measures_sel)
		{
			for (i=0; i < me._measures_sel.length; i++)
			{
				if (me._measures_sel[i] == val)
				{
					sval = i;
					break;
				}
			}
			
			if (sval > -1)
			{
				me.view._refreshMeasureGroup.call(me.view, sval);
			}
		}
	});

	
	me.btnmap = {};
	
	config = config || {};
	config.draggable != false && me.box.draggable({
		handle: me.box_title,
		
		delay: 300,
		distance: 5,
		// zIndex: 99,
		
		start: function(event, ui) {
			if (!owner.editmode)
			{
				if (!me.is_float || (me.is_float && !me.fl_moveable))
					return false;
			}
			
			me.dragging = true;
			
			if (owner.editmode)
			{
				owner.showDropProxy.call(owner, event, ui, me.is_float);
			}
		},
		drag: function(event, ui) {
			if (owner.editmode)
			{
				owner.dragOver.call(owner, event, ui, me.is_float);
			}
		},
		stop: function(event, ui) {
			if (owner.editmode)
			{
				owner.dragStop.call(owner, event, ui, me.is_float);
			}
			else if (me.is_float && me.fl_moveable)
			{
				owner.dragStop.call(owner, event, ui, me.is_float);
			}
			me.dragging = false;
		}
	});
	
	me.box.resizable({
		disabled: true,
		start: function(event, ui) {
			
		},
		stop: function(event, ui) {
			me.val_fl_size();
		}
	});
	
	// me.box.bind("resize", function() {
	// 	if (me.__collapsed)
	// 		return;
	// 	me.resizeH();
	// });

	if (!me._box_obsv)
	{
		var pw, ph;

		if (window.ResizeObserver)
		{
			me._box_obsv = new ResizeObserver(function() {
				var box = me.box[0],
					cw = box.clientWidth,
					ch = box.clientHeight;

				if (cw != pw || ph != ch)
				{
					if (me.__collapsed)
						return;
					
					me.resizeH();
				}
				pw = cw;
				ph = ch;
			}).observe(me.box[0]);
		}
	}
	
	me.bcollapse.bind("click", function() {
		me.set_collapse(false);
	});
	
	me._dzid = me.owner._dzid + "_" + me.docid;

	me.resizeH();
	
	if (config)
	{
		me.fixed_width = typeof(config.fixed_width) != "undefined" ? config.fixed_width : me.fixed_width;
		me.fixed_height = typeof(config.fixed_height) != "undefined" ? config.fixed_height : me.fixed_height;
		me.fit_content_h = typeof(config.fit_content_h) != "undefined" ? config.fit_content_h : me.fit_content_h;
		me.showtitle = !config.hidetitle;
		me.showTitle(me.showtitle);
		me.setTitle(config.title);
		me.setPanelCss(config.panel_css);
		
		me.fl_resizable = config.fl_resizable;
		me.fl_moveable = config.fl_moveable;
		me.hide_maximize = config.hide_maximize;
		me.fl_collapsed = config.fl_collapsed;
		me.fl_collapsible = config.is_float && config.fl_collapsible === true;
		me.fl_collapse_css = config.fl_collapse_css;
		
		me.setFloat(config.is_float);
		
		me.objtype = me.objtype || config.objtype;
	}
	
	me.init();
}

