	initFitH: function() {
		var me = this;

		if (me.objtype == "FILTER" && me.fixed_height && me.fit_content_h && !me._resizeObserver)
		{
			if (window.ResizeObserver)
			{
				me._resizeObserver = new ResizeObserver(function() {
					me.fitH(1);
				}).observe(me.box[0]);

				me._resizeObserver2 = new ResizeObserver(function() {
					me.fitH(2);
				}).observe(me.view.contentarea[0]);
			}
		}
	},
	fitH: function(origin) {
		var me = this;

		me._fitH && clearTimeout(me._fitH);

		me._fitHT = setTimeout(function() {
			me._fitH(origin);
		}, 50);
	},

	_fitH: function(origin) {
		var me = this,
			view = me.view,
			binner = me.binner,
			box_title = me.box_title,
			theight = IG$.j$ext._h(box_title), // box_title.is(":visible") ? box_title.height() + 4 * 3 : 0,
			bheight = binner.height(),
			cheight,
			_pc = me._pc,
			owner = me.owner;

		view.contentarea.css("height", "auto");

		cheight = IG$.j$ext._h(view.contentarea) + 22; // .height() + 4 * 2 + 10 * 2;

		if (!bheight)
			return;

		var n_height = theight + Math.max(cheight, 40);

		if (n_height !== _pc._fh)
		{
			_pc._fh = n_height;
			me.height = n_height;

			// owner.resizeContainer.call(owner, [me]);
			owner.updateDisplay.call(owner, true);
		}
	},

	validateProperty: function(validate_child) {
		var me = this;
		
		switch (me.objtype)
		{
		case "SHEET":
		case "FILTER":
		case "TEXT":
		case "RPT_VIEW":
		case "FB_VIEW":
			me.container = false;
			me.children = [];
			break;
		case "PANEL":
		case "_dc":
		case "TAB":
			me.container = true;
			me._direction = 0; // 0 : horizontal, 1 : vertical
			me.children = [];
			break;
		}

		me.box_container.addClass("panel_" + me.objtype.toLowerCase());
		
		if (me.objtype != "_dc" && me._pc)
		{
			var lparent = me._pc.parent;
			
			while (lparent)
			{
				if (lparent.objtype == "PANEL")
				{
					break;
				}
				
				lparent = lparent.parent;
			}
			
			if (lparent && lparent.lt && lparent.lt.ubody.panel_css && lparent.lt.ubody.panel_css.indexOf("no_border_children") > -1)
			{
				me.panel_css = me.panel_css || "";
				
				if (me.panel_css.indexOf("no_border") < 0)
				{
					me.panel_css += ";" + "no_border";
					
					me.setPanelCss(me.panel_css);
				}
			}
			else if (lparent && lparent.lt && me.panel_css && me.panel_css.indexOf(";no_border") > -1)
			{
				me.panel_css = me.panel_css.replace(";no_border", "");
				me.setPanelCss(me.panel_css);
			}
		}
		
		if (validate_child && me._pc && me._pc.children)
		{
			$.each(me._pc.children, function(i, child) {
				if (child.lt && child.lt.ubody)
				{
					child.lt.ubody.validateProperty(validate_child);
				}
			});
		}
		
		if (me.objtype == "SHEET" && me.view && !me._bind_event)
		{
			me.view.on("_view_changed", function(view) {
				var sop = me.view.sheetoption;
				if (sop && sop.model)
				{
					me.btnmap["selchart"].el[sop.model.tb_chart && me.view.activeView == 1 ? "show" : "hide"]();
				}
			});
			
			me._bind_event = 1;
		}
	},
	
	$upd_exec: function() {
		var me = this,
			vmodel = me.get_sop();
		
		if ((me.is_float && me.owner.editmode) || (vmodel && me.is_float && vmodel.fl_resizable))
		{
			me.box.resizable("enable");
		}
		else
		{
			me.box.resizable("disable");
		}
	},
	
