IG$._FC_combobox = $s.extend(IG$._baseFC, {
	objtype: "combobox",
	s_codemap: 1,
	s_metric: 1,
	events: [
		{name: "change_val"}
	],
	properties: [
		{name: "value", type: "string"},
		{name: "placeholder", type: "string"},
		{name: "selected", type: "object", readonly: true},
		{name: "labelField", type: "string"},
		{name: "valueField", type: "string"}
	],
	create: function(container) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			showpopup = fmodel.showpopup,
			browser = window.bowser,
			ui, lbl$, btnsel,
			rangevalue = fmodel.rangevalue,
			rangelabel = fmodel.rangelabel ? fmodel.rangelabel.split("^") : [],
			fid = me._get_id();
			
		if (showpopup)
		{
			ui = $("<div class='idv-sel-combo'></div>")
				.appendTo(container);
			
			var sinp;
			
			lbl$ = me.lbl$ = $("<label class='form-label' for='" + fid + "'></label>"); // .appendTo(sinp);
			// $("<div class='form-helper'></div>").appendTo(sinp);
			sinp = me.createTextField(ui);
			me.mp$ = sinp[0];
			
			ui.sinp = sinp;

			btnsel = $("<div class='idv-btn-selected idv-float-button'></div>")
				.appendTo(ui)
				.bind("click", function(e) {
					e.stopPropagation();
					
					hfilter = me.form.checkHFilter(fitem);
					
					if (hfilter == false)
						return;
					
					var dlg = new IG$.dynFilter({
						instance: me.instance,
						selModel: {
							mode: "SINGLE",
							selType: "checkboxmodel",
							checkSelector: ".x-grid-cell"
						},
						smode: fitem.smode,
						callback: new IG$.callBackObj(me, me.rs_checkPopup, fitem),
						filteritem: fitem,
						hfilter: hfilter
					});
					IG$.checkLogin(me, dlg);
				});

			sinp.bind("click", function(e) {
				btnsel.trigger("click");
			});
		}
		else
		{
			/*
			ui = $("<table class='idv-sel-combo" + (rangevalue ? " idv-sel-rangevalue" : "") + "'>" + (me.getRangeCol(rangelabel, 0, 0, rangevalue)) + "<col width='*'>" + "<col width='17px'>" + (me.getRangeCol(rangelabel, 0, 1, rangevalue)) + (rangevalue ? "<col width='18px'>" + (me.getRangeCol(rangelabel, 2, 0, rangevalue)) + "<col width='*'><col width='17px'>" + (me.getRangeCol(rangelabel, 2, 1, rangevalue)) : "") + "<tr></tr></table>");
			*/
			ui = $("<div class='idv-sel-combo'></div>")
				.appendTo(container);
			var m1,
				m2 = null,
				ml,
				Lt, Dt, S;
				
			Lt = (me.getRangeLabel(rangelabel, 0, 0, rangevalue));
			
			if (Lt)
			{
				Dt = $(Lt.d).appendTo(ui);
				Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
			}
			
			var fid = me._get_id();
			me.mp$ = me.createTextField(ui, null);
			m1 = $(me.mp$);
			lbl$ = me.lbl$ = $(".mdc-floating-label", me.mp$);
			mdc.textField.MDCTextField.attachTo(me.mp$);

			m1.$btn = $("<div class='idv-sel-combo-button idv-float-button'></div>").appendTo(ui);

			Lt = (me.getRangeLabel(rangelabel, 0, 1, rangevalue));
			
			if (Lt)
			{
				Dt = $(Lt.d).appendTo(ui);
				Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
			}
			
			if (rangevalue)
			{
				Lt = (me.getRangeLabel(rangelabel, 1, 2, rangevalue));
				
				S = $("<div class='igc-f-range-label-td'></div>").appendTo(ui);
				
				if (Lt)
				{
					Dt = $(Lt.d).appendTo(S);
					Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
				}
				
				Lt = (me.getRangeLabel(rangelabel, 2, 0, rangevalue));
				
				if (Lt)
				{
					Dt = $(Lt.d).appendTo(ui);
					Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
				}
				
				var fid = me._get_id();
				me.mp$2 = me.createTextField(ui, null);
				m2 = $(me.mp$2);
				mdc.textField.MDCTextField.attachTo(me.mp$2);
				m2.$btn = $("<div class='idv-sel-combo-button idv-float-button'></div>").appendTo(ui);
				
				Lt = (me.getRangeLabel(rangelabel, 2, 1, rangevalue));
				
				if (Lt)
				{
					Dt = $(Lt.d).appendTo(ui);
					Lt.e && IG$._rrcs(me, Lt.t, $("span", Dt), 1);
				}
			}
			
			ml = rangevalue ? [m1, m2] : [m1]
			
			$.each(ml, function(k, mui) {
				var ui = mui,
					sctrl,
					sbtn;

				sctrl = $("input", ui[0]);
				sbtn = ui.$btn;

				sctrl.__c = true;
				sctrl.bind("input", function(e) {
					e.stopPropagation();
					e.stopImmediatePropagation();
					e.preventDefault();
					return false;
				});
				sctrl.bind("keydown", function(e) {
					if (e.key == "Escape")
					{
						this.value = "";
						ui[0].value = this.value;
					}
				});
				sctrl.bind("click", function(e) {
					$(this).select();
					sbtn.trigger("click");
				});
				
				var api_search = function(response, keyword) {
					var req = new IG$._rpc$(),
						meta_type = "valueinfo",
						address = [],
						cnt = {
							items: [],
							option: "ValueInfo"
						},
						hfilter,
						kfilter,
						fmodel = fitem.model,
						codemapping = fmodel.codemapping;
						
					if (fitem.itemtype == "prompt")
					{
						if (codemapping && codemapping.uid)
						{
							address.push({
								uid: codemapping.uid,
								type: fmodel.type,
								rptid: codemapping.uid
							});
							
							cnt.items.push({
								uid: codemapping.uid,
								cmap: codemapping,
								hfilter: hfilter
							});
						}
					}
					else
					{
						address.push({
							name: fmodel.name,
							uid: fmodel.uid,
							objtype: objtype,
							nodepath: fmodel.nodepath,
							rptid: fmodel.uid,
							sql_id: fmodel.sql_id
						});
						
						cnt.items.push({
							uid: fmodel.uid,
							cmap: codemapping,
							sql_id: fmodel.sql_id,
							hfilter: hfilter
						});
					}
					
					hfilter = me.form.checkHFilter(fitem);
					
					if (keyword.indexOf("%") < 0)
					{
						keyword += "%";
					}
					
					kfilter = {
						ftype: "condition",
						operator: "LIKE",
						fields: [
							address[0]
						],
						values: [
							{code: keyword, value: keyword}
						]
					};
					
					kfilter.fields[0].type = "";
					
					if (!hfilter)
					{
						hfilter = [kfilter];
					}
					else
					{
						hfilter.push(kfilter);
					}
					
					cnt.items[0].hfilter = hfilter;
						
					req.init(me, 
						{
							ack: "olapservice",
							payload: address,
							mbody: cnt,
							meta_type: meta_type
						}, me, function(jdoc) {
							if (jdoc.erroritems && jdoc.erroritems.length)
							{
								$.each(jdoc.erroritems, function(i, eitem) {
									IG$.ShowErrorMessage(eitem, me, null);
								});
								return;
							}
							
							var mchild = IG$.parseValueList(jdoc.value_results),
								i, sdp = [],
								dval,
								data = mchild[0].data,
								d;
							
							for(i=0; i < data.length; i++)
							{
								d = data[i];
								sdp.push({label: (d.disp || d.code), value: d.code});
							}
							
							fitem.kdp = sdp;
							response(sdp);
						}, function(jdoc) {
						});
					req.send();
				}
				
				sctrl.autocomplete({
					minLength: 0,
					sortResults: false,
					sortable: false,
					source: function(request, response) {
						var reqval = request.term,
							eval = reqval.split(/,\s*/),
							sdp = fitem.sdp;
						if (sdp)
						{
							reqval = eval.pop();
							
							fitem.kdp = null;
							
							if (reqval && sdp.length > 190)
							{
								api_search(response, reqval);
							}
							else
							{
								response($.ui.autocomplete.filter(sdp, reqval));
							}
						}
					},
					focus: function(e, ui) {
						return false;
					},
					select: function(e, mobj) {
						var svalue = mobj.item;
						
						if (!svalue.value)
						{
							if (fmodel.showallvalue)
							{
								this.value = "";
								ui[0].value = this.value;
								ui.trigger("change");
							}
						}
						else
						{
							this.value = svalue.label;
							ui[0].value = this.value;
							fitem._svalues = [
								{
									code: svalue.value,
									text: svalue.label
								}
							];
							ui.trigger("change");
						}
						
						if (browser.msie)
						{
							sctrl.blur();
						}
						return false;
					},
					open: function(e, mobj) {
						sctrl.__c = false;
					},
					close: function(e, mobj) {
						sctrl.__c = false;
						setTimeout(function() {
							sctrl.__c = true;
							if (browser.msie)
							{
								sctrl.blur();
							}
						}, 1200);
					}
				});
				
				sctrl.bind("keydown", function(e) {
					if (e.keyCode === $.ui.keyCode.TAB) 
					{
						sctrl.__c = true;
						
						var vmenu = $(this).autocomplete("widget").menu;
						if (vmenu.active)
						{
							e.preventDefault();
						}
					}
					else if (e.keyCode === $.ui.keyCode.ENTER)
					{
						var i,
							m = 0,
							l = sctrl.val().toLowerCase(), 
							v,
							sdp = fitem.sdp,
							kdp = fitem.kdp,
							kdp_i,
							sdp_i;
						
						if (sdp && sdp.length && l)
						{
							v = l.length;
							
							for (i=0; i < sdp.length; i++)
							{
								sdp_i = sdp[i];
								if (sdp_i.label.substring(0, v).toLowerCase() == l)
								{
									fitem._svalues = [
										{
											code: sdp_i.value,
											text: sdp_i.label
										}
									];
									sctrl.val(sdp_i.label);
									ui[0].value = sdp_i.label;
									ui.trigger("change");
									m = 1;
									break;
								}
							}
							
							if (!m && kdp)
							{
								for (i=0; i < kdp.length; i++)
								{
									kdp_i = kdp[i];
									if (kdp_i.label.substring(0, v).toLowerCase() == l)
									{
										fitem._svalues = [
											{
												code: kdp_i.value,
												text: kdp_i.label
											}
										];
										sctrl.val(kdp_i.label);
										ui[0].value = kdp_i.label;
										ui.trigger("change");
										m = 1;
										break;
									}
								}
							}
						}
						if (m)
						{
							sctrl.autocomplete("close");
							sctrl.__c = true;
						}
					}
				});
				
				sbtn.bind("click", function(e) {
					e.stopImmediatePropagation();
					e.stopPropagation();
					e.preventDefault();
					
					if (sctrl.__c)
					{
						sctrl.__c = false;
						sctrl.autocomplete("search", ""); // filter value need to initialized
						sctrl.focus();
					}
					else
					{
						sctrl.__c = true;
						sctrl.autocomplete("close");
					}
				});
				
				ui.bind("change", function() {
					var bchanged = true,
						pkey = "__pval" + k,
						tval = sctrl.val(),
						sctrl_sel,
						sctrl_sel_code = "",
						i, placeholder = sctrl.attr("placeholder"),
						sdp = fitem.sdp,
						sdp_i;
					
					if (sdp && sdp.length)
					{
						for (i=0; i < sdp.length; i++)
						{
							sdp_i = sdp[i];
							
							if (placeholder && tval == placeholder)
							{
								continue;
							}
							else if (sdp_i.value == tval || sdp_i.label == tval)
							{
								sctrl_sel =
									{
										code: sdp_i.value,
										text: sdp_i.text || sdp_i.label
									};
								sctrl_sel_code = sctrl_sel.code;
								break;
							}
						}
					}
					
					if (fitem[pkey] == sctrl_sel_code)
					{
						bchanged = false;
					}
					
					if (bchanged)
					{
						me.clearInvalid();
						fitem[pkey] = sctrl_sel_code;
						
						if (fmodel.type == "valueset")
						{
							fitem.value = [];
							me.form.updateFilterValue(fitem);
							
							if (fitem.value && fitem.value.length && fitem.value[0].code)
							{
								var nvalue = fitem.value[0].code;
								setTimeout(function() {
									me.form._upd_vs_value.call(me.form, nvalue);
								}, 10);
							}
							return false;
						}
						
						if (fmodel.isnecessary)
						{
							!sctrl_sel_code && me.markInvalid("required");
						}
						
						// me.mp$ && me.mp$.update();
						me.trigger("change_val");
					}
				});
			});
		}
		
		return ui;
	},
	loadData: function(data) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			ui = me.ui,
			_init_value = fmodel._init_value || fmodel.initial_values;
			
		if (fmodel.showpopup)
		{
			fitem.selection = [];
			
			// hfilter = me.form.checkHFilter(fitem);
			
			if (_init_value)
			{
				me.rs_checkPopup(_init_value, fitem, false);
			}
		}
		else
		{
			sctrl = me.mp$;
			sctrl1 = me.$mp$2;
			
			sdp = [];
			if (fmodel.showallvalue)
			{
				if (fmodel.isnecessary)
				{
					aname = fmodel.aname || IRm$.r1("L_SELECT_VALUE");
				}
				else
				{
					aname = fmodel.aname || IRm$.r1("L_ALL_VALUE");
				}
				
				sctrl.placeholder = aname;
				if (sctrl1)
					sctrl1.placeholder = aname;

				if (!fmodel.isnecessary)
					sdp.push({label: aname, value: ""});
			}
			
			dval = me.getDefaultValue(fitem, 0);
			
			fitem._svalues = [];
			
			for(let i=0; i < data.length; i++)
			{
				sdp.push({label: (data[i].disp || data[i].code), value: data[i].code});
				if (dval && dval == data[i].code)
				{
					if (fmodel.rangevalue)
					{
						fitem._svalues.push(
							{
								code: data[i].code,
								text: data[i].disp || data[i].code
							}
						);
					}
					else
					{
						fitem._svalues = [
							{
								code: data[i].code,
								text: data[i].disp || data[i].code
							}
						];
					}
				}
			}
			
			if (!fmodel.showallvalue && (!fitem._svalues || (fitem._svalues && fitem._svalues.length == 0)) && sdp.length)
			{
				fitem._svalues = [
					{
						code: sdp[0].value,
						text: sdp[0].label
					}
				];
				
				if (fmodel.rangevalue)
				{
					fitem._svalues.push({
						code: sdp[sdp.length-1].value,
						text: sdp[sdp.length-1].label
					});
				}
			}
			
			if (fitem._svalues && fitem._svalues.length)
			{
				sctrl.value = fitem._svalues[0].text;
				if (fmodel.rangevalue)
				{
					sctrl1.value = fitem._svalues[1].text;
				}
			}
			
			fitem.sdp = sdp;
			// sctrl.trigger("change");
		}
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fmodel = me.fmodel,
			showpopup = fmodel.showpopup,
			ui = me.ui,
			sctrl1, sctrl2;
			
		sctrl1 = me.mp$;
		if (fmodel.rangevalue)
		{
			sctrl2 = me.mp$2;
		}
		
		if (fmodel.showpopup)
		{
			me.rs_checkPopup(svalues, me.fitem, false);
		}
		else
		{
			sctrl1.value = values[0] || "";
			if (sctrl2)
				sctrl2.value = values[1] || "";
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			ui = me.ui,
			sval;
			
		// value = ui.val();
		// disp = $("option:selected", ui).text();
		if (fmodel.showpopup)
		{
			selection = fitem.selection = fitem.selection || [];
			if (selection.length)
			{
				value.push({code: selection[0].code, value: selection[0].value});
			}
		}
		else
		{
			var sctrls;
			
			sctrls = [me.mp$];
			if (fmodel.rangevalue)
			{
				sctrls.push(me.mp$2);
			}
			
			sval = [];
			sdp = fitem.sdp;
			
			$.each(sctrls, function(m, mui) {
				var tval = mui.value,
					placeholder = mui.placeholder,
					i;

				if (!fmodel.rangevalue && tval && fitem._svalues && fitem._svalues.length && fitem._svalues[0].text == tval)
				{
					if (!placeholder || (placeholder && tval != placeholder))
					{
						sval = fitem._svalues;
					}
				}
				else if (tval && sdp && sdp.length)
				{
					for (i=0; i < sdp.length; i++)
					{
						sdp_i = sdp[i];
						if (placeholder && tval == placeholder)
						{
							continue;
						}
						else if (sdp_i.value == tval || sdp_i.label == tval)
						{
							sval.push(
								{
									code: sdp_i.value,
									text: sdp_i.text || sdp_i.label
								}
							);
							break;
						}
					}
				}
			});
			
			if (sval && (!fmodel.rangevalue && sval.length) || (fmodel.rangevalue && sval.length > 1))
			{
				for (let i=0; i < sval.length; i++)
				{
					value.push({code: sval[i].code, value: sval[i].text});
				}
			}
		}
	},
	clear: function() {
		var me = this,
			fmodel = me.fmodel,
			showpopup = fmodel.showpopup,
			ui = me.ui;
			
		if (showpopup)
		{
			$("input[type=text]", ui).val("");
			fitem.selection = [];
		}
		else
		{
			$("option:selected", ui).removeAttr("selected");
		}
	},
	$setProp: function(fitem, key, value) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			sctrls = [$("[name=c_m1]", ui)];
			
		if (fmodel.rangevalue)
		{
			sctrls.push($("[name=c_m2]", ui));
		}
		
		switch(key)
		{
		case "placeholder":
			$.each(sctrls, function(m, mui) {
				mui && mui.attr("placeholder", value);
			});
			break;
		case "value":
			me.setValue([value]);
			break;
		case "labelField":
			break;
		case "valueField":
			break;
		}
		IG$._baseFC.prototype.$setProp.call(me, fitem, key, value);
	}
});

IG$.$FCinst["combobox"] = new IG$._FC_combobox();