IG$.cVis.chord = $s.extend(IG$.cVis.protovis, {
	subtype: "chord",
	draw_protovis: function(mresult) {
		var i,
			j,
			me = this,
			mcr = me.sheetoption ? me.sheetoption.model.chart_option : null,
			data = mresult._tabledata,
			fc = mresult.colfix,
			fr = mresult.rowfix,
			tc = (data.length > 0) ? data[0].length : 0,
			title,
			fields = [],
			matrixdata = [],
			row,
			tn,
			relationgroups = mcr.relationgroups;
	
		mcr.settings = mcr.settings || {};
	
		var jdom = $(me.container),
			w = IG$.j$ext._w(jdom),
			h = IG$.j$ext._h(jdom),
			sep = me.getSep();
			
		// From http://mkweb.bcgsc.ca/circos/guide/tables/
		var me = this,
			cop = me.chart_option,
			chordmatrix = [], row, link, nodenames = [],
			tc = data[0].length,
			chd_method = mcr ? mcr.settings.chd_method || "relations" : "relations",
			range = tc - fc,
			text_sample = [],
			bdraw = 0,
			currentSelectedIndex,
			rel_range1 = (cop.rel_range1 == IG$.UNDEFINED || cop.rel_range1 == null) ? -1 : cop.rel_range1,
			rel_range2 = (cop.rel_range2 == IG$.UNDEFINED || cop.rel_range2 == null) ? 1 : cop.rel_range2;
			
		if (chd_method == "tablematrix")
		{
			var fitems = {},
				fnames = [],
				s = 0,
				fname,
				oitem,
				v,
				_c, _r;
			
			if (fc > 0)
			{
				for (i=fr; i < data.length; i++)
				{
					fname = data[i][0].code;
					if (!fitems[fname])
					{
						oitem = {
							name: fname,
							seq: s,
							r: i,
							c: -1
						};
						fnames.push(oitem);
						s++;
						fitems[fname] = oitem;
						
						text_sample.push({
							title: fname,
							code: fname
						});
					}
				}
				
				for (i=fc; i < tc; i++)
				{
					fname = data[0][i].code;
					
					if (fitems[fname])
					{
						fitems[fname].c = i;
					}
				}
				
				for (i=0; i < fnames.length; i++)
				{
					row = [];
					_r = fnames[i].r;
					
					for (j=0; j < fnames.length; j++)
					{
						_c = fnames[j].c;
						
						v = 0;
						
						if (_c > -1)
						{
							v = Number(data[_r][_c].code) || 0;
						}
						if (v > 0)
						{
							bdraw = 1;
						}
						row.push(v);
					}
					chordmatrix.push(row);
				}
			}
		}
		else
		{
			var relation = me.getRelData(mresult, 2, false, relationgroups, {s: rel_range1, t: rel_range2}),
				range = relation.nodes.length,
				fname;
	
			for (i=0; i < relation.nodes.length; i++)
			{
				row = [];
				fname = relation.nodes[i].nodeName;
				nodenames.push({name: fname});
				for (j=0; j < relation.nodes.length; j++)
				{
					row.push(0);
				}
				text_sample.push({
					title: fname,
					code: fname
				});
				chordmatrix.push(row);
			}
	
			for (i=0; i < relation.links.length; i++)
			{
				link = relation.links[i];
				chordmatrix[link.source][link.target] = (link.value + 1);
				if (link.source != link.target)
				{
					chordmatrix[link.target][link.source] = (link.value + 1);
					bdraw = 1;
				}
			}
		}
	
		if (bdraw == 0)
		{
			return;
		}
			
		var mw = w,
			mh = h,
			c_cset = (mcr ? mcr.colorset : "") || mresult.c_cset,
			innerRadius = Math.min(w, h) * .41,
			outerRadius = innerRadius * 1.1,
			colors = ["#009CFF", "#FBE105", "#72C936", "#C42AD8", "#2164E9", "#FF9600", "#F02F1B"];
	
		if (IG$.__chartoption && IG$.__chartoption.chartcolors && IG$.__chartoption.chartcolors[c_cset])
		{
			colors =  IG$.__chartoption.chartcolors[c_cset];
		}
	
		var svg = me.vis = d3.select(me.container).append("svg:svg")
			.attr("width", mw)
			.attr("height", mh)
			.attr("viewBox", [-mw / 2, -mh / 2, mw, mh]);
	
		var formatValue = d3.format(".1~%");
		var chords = d3.chord()
			.padAngle(10 / innerRadius)
			.sortSubgroups(d3.descending)
			.sortChords(d3.descending)
			(chordmatrix);
			
		var arc = d3.arc()
			.innerRadius(innerRadius)
			.outerRadius(outerRadius);
		var ribbon = d3.ribbon();
		ribbon.radius(innerRadius - 1);
		// ribbon.padAngle(1 / innerRadius);
			
		var color = d3.scaleOrdinal(nodenames, colors);
		var tickStep = d3.tickStep(0, d3.sum(chordmatrix.flat()), 100);
	
		function ticks(_ref) {
			var startAngle = _ref.startAngle,
				endAngle = _ref.endAngle,
				value = _ref.value;
			var k = (endAngle - startAngle) / value;
			return d3.range(0, value, tickStep).map(function (value) {
				return {
					value: value,
					angle: value * k + startAngle
				};
			});
		}
	
		var group = svg.append("g");
	
		group = group.attr("font-size", 10)
			.attr("font-family", "sans-serif");
			
		group = group.selectAll("g");
		group = group.data(chords.groups)
		group = group.join("g");
			
		group.append("path")
			.attr("fill", function(d) {
				return color(nodenames[d.index].name);
			})
			.attr("d", arc);
			
		group.append("title")
			.text(function(d) {
				return "".concat(nodenames[d.index].name, "\n").concat(formatValue(d.value));
			});
		var groupTick = group.append("g")
			.selectAll("g")
			.data(ticks)
			.join("g")
			.attr("transform", function(d) {
				return "rotate(".concat(d.angle * 180 / Math.PI - 90, ") translate(").concat(outerRadius, ",0)");
			});
		groupTick.append("line")
			.attr("stroke", "currentColor")
			.attr("x2", 6);
	
		groupTick.append("text")
			.attr("x", 8)
			.attr("dy", "0.35em")
			.attr("transform", function(d) {return d.angle > Math.PI ? "rotate(180) translate(-16)" : null;})
			.attr("text-anchor", function(d) {return d.angle > Math.PI ? "end" : null;})
			.text(function(d) {return formatValue(d.value)});
	
		group.select("text")
			.attr("font-weight", "bold")
			.text(function(d) {
				return this.getAttribute("text-anchor") === "end" ? "\u2191 ".concat(nodenames[d.index].name) : "".concat(nodenames[d.index].name, " \u2193");
			});
	
		svg.append("g")
			.attr("fill-opacity", 0.8)
			.selectAll("path")
			.data(chords)
			.join("path")
			.style("mix-blend-mode", "multiply")
			.attr("fill", function (d) {
				return color(nodenames[d.source.index].name);
			})
			.attr("d", ribbon)
			.append("title")
			.text(function (d) {
				return "".concat(formatValue(d.source.value), " ").concat(nodenames[d.target.index].name, " \u2192 ").concat(nodenames[d.source.index].name).concat(d.source.index === d.target.index ? "" : "\n".concat(formatValue(d.target.value), " ").concat(nodenames[d.source.index].name, " \u2192 ").concat(nodenames[d.target.index].name));
			});
	
	}
});