// clipboard.js
// for non ie version, clipboard copy in system is blocked.
// make textarea to user action to copy clipboard.
IG$.c$ClpBrd = $s.extend($s.window, {
	
	modal: true,
	region:'center',
	layout: {
		type: 'fit',
		align: 'stretch'
	},
	
	closable: false,
	resizable:false,
	width: 500,
	height: 400,
	
	init_f: function() {
		var me = this,
			outputtype = me.down("[name=outputtype]"),
			p_page = me.down("[name=p_page]"),
			n_page = me.down("[name=n_page]"),
			mresult = me.mresult;
			
		if (mresult && mresult.rowcnt > mresult._tabledata.length)
		{
			n_page.setValue("Partial page start " + (mresult.pagestart + 1) + " to " + (mresult.pageend + 1));
			p_page.show();
		}
		
		outputtype.setValue("comma");
		
		me.setOutTxt();
	},
	
	changeOutTyp: function() {
		var me = this;
		me.setOutTxt();
	},
	
	setOutTxt: function() {
		var me = this,
			outputtype = me.down("[name=outputtype]"),
			textoutput = me.down("[name=textoutput]"),
			tableoutput = me.down("[name=tableoutput]"),
			btntableview = me.down("[name=btntableview]"),
			mresult = me.mresult,
			data = (mresult && mresult._tabledata && mresult._tabledata.length > 0) ? mresult._tabledata : null,
			tout = [],
			ot = outputtype.getValue(),
			dom = $(tableoutput.body.dom),
			i, j, t, tvar, delim = ",", israw = false, bquote = "", istable = false;
		
		if (data)
		{
			switch (ot)
			{
			case "tab":
				delim = "\t";
				break;
			case "comma":
				bquote = "\"";
				break;
			case "rawcomma":
				israw = true;
				break;
			case "rawtab":
				israw = true;
				delim = "\t";
				break;
			case "table":
				istable = true;
				break;	
			}
			
			if (istable == false)
			{
				btntableview.setVisible(false);
				for (i=0; i < data.length; i++)
				{
					t = "";
					for (j=0; j < data[i].length; j++)
					{
						tvar = bquote + ((israw == true) ? (data[i][j].code || "") : (data[i][j].text || data[i][j].code || "")) + bquote;
						t = (j == 0) ? tvar : t + delim + tvar;
					}
					tout.push(t);
				}
			}
			else
			{
				btntableview.setVisible(true);
				btntableview.setValue(false);
				
				tout.push("<table>");
				for (i=0; i < data.length; i++)
				{
					t = "<tr>";
					for (j=0; j < data[i].length; j++)
					{
						tvar = "<td>" + (data[i][j].text || data[i][j].code || "&nbsp;") + "</td>";
						t += tvar;
					}
					tout.push(t + "</tr>");
				}
				
				tout.push("</table>");
				
				dom.empty();
				dom.html(tout.join(""));
				// dom.children().selText();
			}
		}
		textoutput.setVisible(true);
		tableoutput.setVisible(false);
		textoutput.setValue(tout.join("\n"));
	},
	
	changeViewMode: function() {
		var me = this,
			// outputtype = me.down("[name=outputtype]"),
			textoutput = me.down("[name=textoutput]"),
			tableoutput = me.down("[name=tableoutput]"),
			btntableview = me.down("[name=btntableview]"),
			tbmode = btntableview.getValue();
		
		textoutput.setVisible(!tbmode);
		tableoutput.setVisible(tbmode);
	},
	
	getAllData: function() {
		var me = this,
			sheetview = me.sheetview,
			mresult = me.mresult,
			doc,
			payload;
		
		doc = sheetview.reportoption.getCurrentPivot();
		
		payload = sheetview.olapset.requestPivotResult(
			doc, null, sheetview.sheetindex, null, 0, mresult.rowcnt + 10, 
			new IG$.callBackObj(me, function(p) {
				var me = this,
					n_page = me.down("[name=n_page]");
					
				if (p && !p.iserror && p.mresults && p.mresults.results.length)
				{
					me.mresult = p.mresults.results[0];
					
					n_page.setValue("Data Fetched... " + (me.mresult._tabledata.length) + " Rows");
					
					me.setOutTxt();
				}
				else
				{
					n_page.setValue("Error while fetching data from server..");
				}
			}), 
			sheetview._job, true, true);
			
		if (payload.payload)
		{
			sheetview.fireEvent("runsheet", sheetview, payload);
		}
	},
	
	initComponent : function() {
		var panel = this;
		
		panel.title = IRm$.r1('L_CLIPBOARD_COPY');
				 
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					bodyBorder: false,
					layout: {
						type: "vbox",
						align: "stretch"
					},
					items: [
						{
							name: "outputtype",
							xtype: "combobox",
							fieldLabel: IRm$.r1("L_OUTPUT_TYPE"),
							queryMode: "local",
							displayField: "name",
							valueField: "value",
							editable: false,
							autoSelect: true,
							store: {
								xtype: "store",
								fields: [
									"name", "value"
								],
								data: [
									{name: "Tab separated", value: "tab"},
									{name: "Comma separated", value: "comma"},
									{name: "Raw data (Tab)", value: "rawtab"},
									{name: "Raw data (Comma)", value: "rawcomma"},
									{name: "HTML Table format", value: "table"}
								]
							},
							listeners: {
								change: function(field, newvalue, oldvalue, opt) {
									panel.changeOutTyp();
								}
							}
						},
						{
							xtype: "fieldcontainer",
							name: "p_page",
							hidden: true,
							layout: {
								type: "hbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "displayfield",
									name: "n_page",
									value: "-",
									flex: 1
								},
								{
									xtype: "button",
									text: IRm$.r1("L_FETCH_ALL"),
									handler: function() {
										this.getAllData();
									},
									scope: this
								}
							]
						},
						{
							xtype: "fieldcontainer",
							layout: "hbox",
							items: [
								{
									xtype: "displayfield",
									value: IRm$.r1("D_CLIPBOARD"), // "Press Ctrl-A then Ctrl-C to copy this content to clipboard!",
									flex: 1
								},
								{
									xtype: "checkbox",
									name: "btntableview",
									boxLabel: IRm$.r1("L_SHOW_HTML"), // "Show HTML",
									hidden: true,
									flex: 1,
									listeners: {
										change: function(field, nvalue, ovalue, eOpts) {
											panel.changeViewMode();
										}
									}
								}
							]
						},
						{
							xtype: "textarea",
							name: "textoutput",
							flex: 1
						},
						{
							html: "",
							collapsible: false,
							name: "tableoutput",
							hidden: true,
							autoScroll: true,
							flex: 1
						}
					]
				}
			],
			buttons:[
				{
					text: IRm$.r1('B_CLOSE'),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function(ui) {
					this.init_f();
				}
			}
		});
		
		IG$.c$ClpBrd.superclass.initComponent.apply(this, arguments);
	}
});
