IG$.p$ChartSlice = $s.extend(IG$.v$pnl, {
	title: "Chart Slicer",
	
	xtype: "panel",
	
	layout: {
		type: "vbox",
		align: "stretch"
	},
	
	maincontainer: null,
	
	floating: true,
	toFrontOnShow: true,
	width: 220,
	hidden: true,
	
	sheetoption: null,
	bInit: false,
	
	applyChanges: function() {
		var i,
			slicemeasures = this.down("[name=slicemeasures]"),
			value;
		
		this.sheetoption.chartPivot.measures = [];
			
		for (i=0; i < slicemeasures.store.data.items.length; i++)
		{
			value = slicemeasures.store.data.items[i].data;
			this.sheetoption.chartPivot.measures.push(value);
		}
		
		this.hide();
		
		this.maincontainer.updateReport();
	},
	
	dropSliceArea: function(item, dropped) {
		var i,
			slicemetrics = this.down("[name=slicemetrics]"),
			slicemeasures = this.down("[name=slicemeasures]");
			
		if (dropped == true)
		{
			for (i=0; i < slicemetrics.store.data.items.length; i++)
			{
				if (slicemetrics.store.data.items[i].data.uid == item.uid)
				{
					slicemetrics.store.remove(slicemetrics.store.data.items[i]);
					break;
				}
			}
		}
		else if (dropped === false)
		{
			slicemetrics.store.add(item);
		}
	},
	
	tools: [
		{
			type: 'minimize',
			qtip: 'Minimize',
			cls: 'x-tool-minimize',
			handler: function(event, toolEl, panel) {
				var p = panel.ownerCt;
				p.hide();
			},
			scope: this
		},
		{
			type: 'gear',
			qtip: 'Close',
			handler: function(event, toolEl, panel) {
				var p = panel.ownerCt;
				p.applyChanges();
			},
			scope: this
		}
	],
	
	applySheetOption: function() {
		var panel = this;
		
		if (this.sheetoption && this.bInit == true)
		{
			var dp = [], 
				dpm=[],
				i,
				eitem = {},
				uid, slicemetrics = this.down("[name=slicemetrics]"),
				slicemeasures = this.down("[name=slicemeasures]");
				
			for (i=0; i < this.sheetoption.chartPivot.clusters.length; i++)
			{
				uid = this.sheetoption.chartPivot.clusters[i].uid;
				eitem[uid] = true;
			}
			
			for (i=0; i < this.sheetoption.chartPivot.rows.length; i++)
			{
				uid = this.sheetoption.chartPivot.rows[i].uid;
				eitem[uid] = true;
			}
			
			for (i=0; i < this.sheetoption.chartPivot.measures.length; i++)
			{
				uid = this.sheetoption.chartPivot.measures[i].uid;
				dpm.push(IG$.CloneObject(this.sheetoption.chartPivot.measures[i]));
				eitem[uid] = true;
			}
			
			$.each(["rows", "cols", "measures", "queryItems"], function(ind, value) {
				for (i=0; i < panel.sheetoption[value].length; i++)
				{
					uid = panel.sheetoption[value][i].uid;
					if (typeof eitem[uid] == 'undefined')
					{
						dp.push(IG$.CloneObject(panel.sheetoption[value][i]));
					}
				}
			});
			
			slicemetrics.store.loadData(dp, false);
			slicemeasures.store.loadData(dpm, false);
		}
	},
	
	initComponent: function() {
		var me = this;
		
		IG$.apply(this, {
			items: [
				{
					xtype: "gridpanel",
					name: "slicemetrics",
					hideHeaders: true,
					flex: 1,
					enableDragDrop: true,
					enableDD: true,
					useArrows: true,
					ddGroup: 'SliceDDGroup',
										
					store: {
						fields: [
							"name", "type", "nodepath", "uid", "itemtype"
						]
					},
					columns: [
						{
							text: IRm$.r1('B_NAME'),
							flex: 1,
							sortable: false,
							dataIndex: 'name'
						}
					]
				},
				{
					xtype: "displayfield",
					text: IRm$.r1("L_MEASURES"), // "Measures",
					border: false
				},
				{
					xtype: "gridpanel",
					name: "slicemeasures",
					hideHeaders: true,
					flex: 1,
					store: {
						fields: [
							"name", "type", "uid", "nodepath", "itemtype"
						]
					},
					viewConfig: {
						plugins: {
							ptype: 'gridviewdragdrop',
							ddGroup: 'SliceDDGroup'
						},
						listeners: {
							beforedrop: function(node, data, dropRec, dropPosition, dropFunction) {
								var r = true,
									index,
									rc = (data.records && data.records.length > 0) ? data.records[0] : null,
									location = (dropRec) ? dropRec.data.location : null, 
									hasitem = false, 
									typename = rc.get("type") || rc.get("itemtype"),
									i;
									
								data.copy = false;
								
								if (typename !== "Measure")
									r = false;
								
								return r;
							},
							
							drop: function(node, data, dropRec, dropPosition) {
								var dropOn = dropRec ? ' ' + dropPosition + ' ' + dropRec.get('name') : ' on empty view',
									rc = (data.records && data.records.length > 0) ? data.records[0] : null,
									typename = rc.get("type") || rc.get("itemtype");
									
								if (typename == "Measure")
								{
									return true;
								}
								
								return false;
							}
						}
					},
					columns: [
						{
							text: IRm$.r1('B_NAME'),
							flex: 1,
							sortable: false,
							dataIndex: 'name'
						},
						{
							xtype: 'actioncolumn',
							width: 20,
							items: [
								{
									iconCls: "icon-grid-delete",
									tooltip: IRm$.r1("B_REMOVE"),
									handler: function (grid, rowIndex, colIndex) {
										var slicemetrics = me.down("[name=slicemetrics]");
										var dt = grid.store.data.items[rowIndex].data;
										grid.store.remove(grid.store.data.items[rowIndex]);
										slicemetrics.store.add(dt);
									},
									scope: this
								}
							]
						}
					]
				}
			],
			buttons: [
				{
					xtype: "button",
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						var p = me;
						p.applyChanges();
					},
					scope: this
				},
				{
					xtype: "button",
					text: IRm$.r1("B_CLOSE"),
					handler: function() {
						var p = me;
						p.hide();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					this.bInit = true;
					this.applySheetOption();
				}
			}
		});
		
		IG$.p$ChartSlice.superclass.initComponent.call(this);
	}
});
