IG$.createAppPanel = function(instance, uid, itemtype, name, address, writable, opt, callback) {
	var p = null,
		popt = {uid: uid, writable: writable, instance: instance}, key, // val,
		modname,
		modetype,
		scripts,
		mod, i, j;
	
	mod = IG$._app_module_[itemtype];
	
	if (mod && mod.opt)
	{
		for (key in mod.opt)
		{
			popt[key] = mod.opt[key];
		}
	}
	
	if (!mod)
		return;

	if (opt)
	{
		for (key in opt)
		{
			popt[key] = opt[key];
		}
	}

	modname = mod.name;
	modetype = mod.modetype || "igcn";
	
	if (modname)
	{
		if (IG$[modname])
		{
			p = new IG$[modname](popt);
		}
		else
		{
			if (typeof(modetype) == "object" && modetype.length)
			{
				scripts = [];
				
				for (i=0; i < modetype.length; i++)
				{
					var ms = ig$.bootconfig.scmap[modetype[i]];
					
					for (j=0; j < ms.length; j++)
					{
						scripts.push(ms[j]);
					}
				}
			}
			else
			{
				scripts = ig$.bootconfig.scmap[modetype];
			}
			
			IG$.getScriptCache(
				scripts, 
				new IG$.callBackObj(this, function() {
					if (IG$[modname])
					{
						callback && callback.execute();
					}
					else
					{
						IG$.ShowError(IRm$.r1("L_ERR_L_MOD"));
					}
				})
			);
		}
	}
	
	return p;
};

IG$.showHelp = function(helpuid, modal, docmode, instance) {
	var h = new IG$.helpWindow({
			uid: helpuid, 
			instance: instance,
			modal: (modal === false) ? false : true,
			dm: docmode || null
		});
		
	if (docmode != "report")
	{
		IG$.loadHelp(helpuid, h);
	}
	else
	{
		h.show();
	}
};

IG$.showHideAllWindow = function(instance, b_show) {
	var i;
	
	if (instance.mainPanel)
	{
		for (i=instance.mainPanel.items.length - 1; i>=0; i--)
		{
			instance.mainPanel.items.items[i].close();
		}
	}	
};

IG$.create_meta = function(instance) {
	var me = this,
		dlgitemsel = new IG$.metaSelectDlg({
			instance: instance,
			mode: "newitem",
			initpath: null,
			callback: new IG$.callBackObj(me, function(item) {
				var me = this,
					meta_type = "business_object",
					main_panel = instance.mainPanel,
					req = new IG$._rpc$();
				
				req.init(me, 
					{
						ack: "writecontent",
						payload: {
							address: item.nodepath + "/" + item.name,
							name: item.name,
							type: "Bobject",
							pid: item.uid
						},
						mbody: {meta_type: meta_type}, //{}
						meta_type: meta_type
					}, me, function(jdoc) {
						var item = jdoc;
						main_panel && main_panel.navigateApp.call(main_panel, item.uid, item.type.toLowerCase(), item.name, item.uid, true, item.writable, {
							opt_editmode: item.writable
						});
					});
				req.send();
			})
		});
	IG$.checkLogin(this, dlgitemsel);
}

