IG$.cellwizard = $s.extend($s.window, {
	
	modal: false,
	layout: "fit",
	resizable:false,
	isWindow: true,
	closeAction: "destroy",
	width: 600,
	height: 620,
	
	_confirm: function() {
		this.saveContent();
	},
	
	_init: function() {
		var me = this,
			req = new IG$._rpc$();
		
		if (me.uid)
		{
			req.init(me, 
				{
					ack: "content",
					payload: {uid: me.uid},
					mbody: {option: 'diagnostics'}
				}, me, me.rs_loadCnt, null);
			req.send();
		}
		else if (me.parentuid)
		{
			me.rs_loadCnt({
				content: {
					meta_type: "chart_measure"
				}
			});
		}
	},
	
	rs_loadCnt: function(jdoc) {
		var me = this,
			node = jdoc.content,
			ctrl, req = new IG$._rpc$(),
			i;
		
		me.down("[name=itemname]").setValue(jdoc.name);
		me.down("[name=description]").setValue(jdoc.description);
		
		me.item = node;
		
		me._ropt = "basedatatype;valuemax;valuemin;cellwidth;cellheight".split(";");
		
		for (i=0; i < me._ropt.length; i++)
		{
			ctrl = me.down("[name=" + me._ropt[i] + "]");
			ctrl.setValue(node[me._ropt[i]]);
		}
		
		$.each(["linecolor", "fillcolor"], function(i, k) {
			me.down("[name=" + k + "]").setValue(node[k]);
		});
		
		ctrl = me.down("[name=axismetric]");
		ctrl.store.loadData(node.axis_metrics);
		
		if (node.value_metric)
		{
			ctrl = me.down("[name=valuemetric]");
			ctrl.setValue(node.value_metric.name);
		}
		
		if (!me.item.cubeuid)
		{
			IG$.getParentCube.call(me, me.uid, me.parentuid, new IG$.callBackObj(me, function(jdoc) {
				me.rs_getCubeInfo(jdoc);
			}));
		}
	},
	
	rs_getCubeInfo: function(jdoc) {
		var me = this,
			tnode = jdoc && jdoc.length ? jdoc[0] : null;
		
		if (tnode)
		{
			me.item.cubeuid = tnode.uid;
		}
	},	
	
	saveContent: function() {
		var ctrl,
			me = this,
			i,
			item = me.item;
			
		if (!IG$.checkFields(me, ["itemname"]))
			return;
		
		item.name = me.down("[name=itemname]").getValue();
		item.description = me.down("[name=description]").getValue();
		
		for (i=0; i < me._ropt.length; i++)
		{
			ctrl = me.down("[name=" + me._ropt[i] + "]");
			item[me._ropt[i]] = ctrl.getValue();
		}
		
		$.each(["linecolor", "fillcolor"], function(i, k) {
			item[k] = me.down("[name=" + k + "]").getValue();
		});
				
		item.axis_metrics = [];
		ctrl = me.down("[name=axismetric]");
		
		for (i=0; i < ctrl.store.data.items.length; i++)
		{
			var dcell = ctrl.store.data.items[i].data;
			item.axis_metrics.push(dcell);
		}
			
		var req = new IG$._rpc$();
		req.init(me, 
			{
				ack: "writecontent",
				payload: {uid: me.uid, pid: me.parentuid, name: item.name, description: item.description, type: me.itemtype, nodepath: (me.parentnodepath ? me.parentnodepath + "/" + item.name : null)},
				mbody: item,
				meta_type: "chart_measure"
			}, me, me.rs_saveContent, null, null);
		req.send();
	},
	
	rs_saveContent: function(jdoc) {
		var me = this;
		IG$.alertmsg(ig$.appname, IRm$.r1("M_SAVED"), null, null, 0, "success");
		me.callback && me.callback.execute(me.item);
		me.close();
	},
	
	valSelHdlr: function(item) {
		var me = this;
		me.item.value_metric = item;
		me.down("[name=valuemetric]").setValue(item.name);
	},
	
	initComponent : function() {
		var me = this;
		
		me.title = "Cell Chart Options";
		
		$s.apply(this, {
			items: [
				{
					xtype: "panel",
					border: 0,
					
					layout: "anchor",
					autoScroll: true,
					padding: ig$.padding,
					
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("B_GENERAL"),
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: "textfield",
									name: "itemname",
									_fasl: 1,
									fieldLabel: IRm$.r1("B_NAME"),
									required: true
								},
								{
									xtype: "textarea",
									hidezoom: true,
									name: "description",
									fieldLabel: IRm$.r1("B_DESC")
								},
							]
						},
						{
							xtype: "combobox",
							name: "basedatatype",
							fieldLabel: IRm$.r1("L_DATA_TYPE"),
							queryMode: 'local',
							displayField: 'name',
							valueField: 'value',
							editable: false,
							autoSelect: true,
							store: {
								xtype: 'store',
								fields: [
									"name", "value"
								],
								data: [
									{name: IRm$.r1("L_CH_PERCENT_GAUGE"), value: 0},
									// {name: "Balloon", value: 1},
									{name: IRm$.r1("L_CH_AREA"), value: 2},
									{name: IRm$.r1("L_CH_LINE"), value: 3},
									{name: IRm$.r1("L_CH_COLUMN"), value: 4},
									// {name: "Bar", value: 5},
									// {name: "100% Bar", value: 6},
									{name: IRm$.r1("L_CH_WINLOSE"), value: 7},
									{name: IRm$.r1("L_CH_PIE"), value: 8},
									{name: IRm$.r1("L_CH_BOXPLOT"), value: 9}
								]
							}
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_YAXIS_SETTING"), // "Y Axis Setting",
							layout: "anchor",
							items: [
								{
									xtype: "numberfield",
									name: "valuemin",
									fieldLabel: IRm$.r1("L_MINIMUM"),
									flex: 1
								},
								{
									xtype: "numberfield",
									name: "valuemax",
									fieldLabel: IRm$.r1("L_MAXIMUM"),
									flex: 1
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_FIELD_SELECTIONS"), // "Field Selections",
							layout: {
								type: "vbox",
								align: "stretch"
							},
							items: [
								{
									xtype: 'fieldcontainer',
									fieldLabel: IRm$.r1("L_VALUE_FIELD"),
									layout: {
										type: 'hbox',
										align: "stretch"
									},
									
									items: [
										{
											xtype: "textfield",
											name: "valuemetric",
											readOnly: true,
											emptyText: IRm$.r1("M_SEL_ITEM")
										},
										{
											xtype: 'button',
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											handler:function() {
												var dlgitemsel = new IG$.metaSelectDlg({
													instance: me.instance,
													visibleItems: 'bobject;table;folder;metric;measure;dataset;formulameasure;custommetric;datemetric',
													tree_options: {
														cubebrowse: true,
														rootuid: me.item.cubeuid
													}
												});
												dlgitemsel.callback = new IG$.callBackObj(this, this.valSelHdlr);
												IG$.checkLogin(this, dlgitemsel);
											},
											scope: this
										}
									]
								},
								{
									xtype: "container",
									layout: {
										type: "hbox",
										align: "stretch",
										pack: "center"
									},
									items: [
										{
											xtype: "gridpanel",
											name: "axismetric",
											title: IRm$.r1("L_XAXIS_FIELD"), // "X-Axis Field",
											hideHeaders: true,
											stateful: true,
											store: {
												fields: [
													"name", "type", "uid", "nodepath"
												]
											},
											flex: 1,
											height: 110,
											viewConfig: {
												plugins: {
													ptype: 'gridviewdragdrop',
													ddGroup: '_I$RD_G_'
												},
												
												listeners: {
													beforedrop: function(node, data, dropRec, dropPosition, dropFunction) {
														var r = false,
															index,
															i, bexist = false,
															rc = (data.records && data.records.length > 0) ? data.records[0] : null;
															
														(this == data.view) ? data.copy = false : data.copy = true;
														
														index = (dropRec) ? this.me.store.indexOf(dropRec) : 0;
															
														if (rc && (rc.data.type == 'Metric' || rc.data.type == 'Measure' || rc.data.type == "CustomMetric" || rc.data.type == "FormulaMeasure" || rc.data.type == "DateMetric"))
														{
															for (i=0; i < this.store.data.items.length; i++)
															{
																if (this.store.data.items[i].data.uid == rc.data.uid)
																{
																	bexist = true;
																	break;
																}
															}
															
															if (bexist == false)
															{
																this.store.add(rc.data);
															}
														}
															
														return r;
													},
													
													drop: function(node, data, dropRec, dropPosition) {
														var dropOn = dropRec ? ' ' + dropPosition + ' ' + dropRec.get('name') : ' on empty view';
														return false;
													}
												}
											},
											columns: [
												{
													text: IRm$.r1('B_NAME'),
													flex: 1,
													sortable: false,
													dataIndex: 'name'
												},
												{
													text: IRm$.r1('B_TYPE'),
													flex: 1,
													sortable: false,
													dataIndex: 'type'
												},
												{
													xtype: 'actioncolumn',
													width: 30,
													items: [
														{
															iconCls: "icon-grid-delete",
															tooltip: 'Delete item',
															handler: function (grid, rowIndex, colIndex) {
																var store = grid.store,
																	rec = store.getAt(rowIndex);
																store.remove(store.data.items[rowIndex]);
															}
														}
													]
												}
											]
										},
										{
											xtype: "button",
											iconCls: "icon-toolbar-search",
											tooltip: IRm$.r1("B_SEARCH"),
											width: 40,
											handler: function() {
												var dlgitemsel = new IG$.metaSelectDlg({
													instance: me.instance,
													visibleItems: 'bobject;table;folder;metric;measure;formulameasure;custommetric;datemetric',
													tree_options: {
														cubebrowse: true,
														rootuid: me.item.cubeuid
													},
													multiselect: true,
													callback: new IG$.callBackObj(this, function(item) {
														var axismetric = this.down("[name=axismetric]"),
															rec,
															store = axismetric.store,
															i, bf = false;
															
														for (i=0; i < store.data.items.length; i++)
														{
															rec = store.data.items[i];
															
															if (rec.get("uid") == item.uid)
															{
																bf = true;
																break;
															}
														}
														
														if (bf == false)
														{
															store.add(item);
														}
													})
												});
												IG$.checkLogin(this, dlgitemsel);
											},
											scope: this
										}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_OPTIONS"), // "Options",
							layout: "anchor",
							items: [
								{
									xtype: "fieldcontainer",
									anchor: "100%",
									fieldLabel: IRm$.r1("L_LINE_COLOR"),
									layout: "hbox",
									items: [
										{
											xtype: "textfield",
											name: "linecolor",
											width: 120
										},
										{
											xtype: "splitter"
										},
										{
											xtype: 'splitbutton',
											width: 30,
											menu: {
												showSeparator: false,
												items: [
													{
														xtype: "colorpicker",
														listeners: {
															select: function(cp, color) {
																this.down("[name=linecolor]").setValue("#" + color);
															},
															scope: me
														}
													}, 
													'-'
												]
											}
										}
									]
								},
								{
									xtype: "fieldcontainer",
									anchor: "100%",
									fieldLabel: IRm$.r1("L_FILL_COLOR"),
									layout: "hbox",
									items: [
										{
											xtype: "textfield",
											name: "fillcolor",
											width: 120
										},
										{
											xtype: "splitter"
										},
										{
											xtype: 'splitbutton',
											width: 30,
											menu: {
												showSeparator: false,
												items: [
													{
														xtype: "colorpicker",
														listeners: {
															select: function(cp, color) {
																this.down("[name=fillcolor]").setValue("#" + color);
															},
															scope: me
														}
													}, 
													'-'
												]
											}
										}
									]
								},
								{
									xtype: "numberfield",
									fieldLabel: IRm$.r1("B_WIDTH"),
									name: "cellwidth",
									minValue: 50,
									maxValue: 400
								},
								{
									xtype: "numberfield",
									fieldLabel: IRm$.r1("B_HEIGHT"),
									name: "cellheight",
									minValue: 20,
									maxValue: 300
								}
							]
						}
					]
				}
			],
			
			buttons:[
				"->",
				{
					text: IRm$.r1('B_CONFIRM'),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				},
				{
					text: IRm$.r1('B_CLOSE'),
					handler: function() {
						this.close();
					},
					scope: this
				}
			],
			
			listeners: {
				afterrender: function(ui) {
					this._init();
				}
			}
		});
		
		IG$.cellwizard.superclass.initComponent.apply(this, arguments);
	}
});