/* file: cellconfig.js */

IG$.dlgCellConfig = $s.extend($s.window, {
	
	modal: true,
	region:"center",
	layout: {
		type: "vbox",
		align: "stretch"
	},
	
	closable: false,
	resizable:false,
	width: 600,
	height: 620,
	
	sheetoption: null,
	
	callback: null,
		
	_confirm: function() {
		var me = this,
			item = me.item || null,
			record = me.record || null;
		
		if (item && record)
		{
			var optsortdir = me.down("[name=cb_sortdir]"),
				sortorder = optsortdir.getGroupValue(),
				cb_sorttype = me.down("[name=cb_sorttype]"),
				sorttype = me.down("[name=cb_sorttype]").getGroupValue(),
				i, j,
				itemtype = me.item.itemtype,
				sheetformula = (me.sheetoption) ? me.sheetoption.model.sheet_formula : null;
				
			record.set("sortorder", (sortorder == "") ? null : sortorder);
			record.set("memo", (sorttype == "") ? null : sorttype);
			record.set("aggrfunc", me.down("[name=aggrfunc]").getValue());
			record.set("disp_title", me.down("[name=disp_title]").getValue());
			record.set("hidecolumn", me.down("[name=hidecolumn]").getValue());
			record.set("timeformat", me.down("[name=timeformat]").getValue());
			
			if (itemtype == "Measure" || itemtype == "FormulaMeasure" || itemtype == "MeasureGroup")
			{
				record.set("activeformula", null);
			}
		}
		
		if (me.callback)
		{
			me.callback.execute();
		}
		
		me.close();
	},
	
	init_f: function() {
		var me = this;
		
		me.formulas = [];
		
		if (me.item)
		{
			var sortorder = me.item.sortorder || "",
				optsortdir = me.down("[name=optsortdir]"),
				sorttype = me.item.memo || "",
				optsorttype = me.down("[name=optsorttype]"),
				aggrfunc = me.down("[name=aggrfunc]"),
				disp_title = me.down("[name=disp_title]"),
				timeformat = me.down("[name=timeformat]"),
				hidecolumn = me.down("[name=hidecolumn]"),
				i, sheetformula, itemtype = me.item.itemtype;
			
			optsortdir.setValue({cb_sortdir: [sortorder]});
			optsorttype.setValue({cb_sorttype: [sorttype]});
			aggrfunc.setValue(me.item.aggrfunc || "");
			disp_title.setValue(me.item.disp_title || "");
			timeformat.setValue(me.item.timeformat || "");
			hidecolumn.setValue(me.item.hidecolumn);
			
			if (me.sheetoption && me.sheetoption.model.sheet_formula)
			{
				sheetformula = me.sheetoption.model.sheet_formula;
				
				for (i=0; i < sheetformula.length; i++)
				{
					if (sheetformula[i].baseuid == me.item.uid)
					{
						me.formulas.push(sheetformula[i]);
					}
				}
				
				me.down("[name=grd_formula]").store.loadData(me.formulas);
			}
		}
	},
	
	editFormula: function(rec) {
		var me = this,
		formulas = me.sheetoption.model.sheet_formula,
		uitem = me.item;
		
		if (rec)
		{
			dlg = new IG$.dlgFormulaConfig({
				instance: me.instance,
				rec: rec,
				sheetoption: me.sheetoption,
				uitem: uitem
			});
		}
		else
		{
			dlg = new IG$.dlgFormulaSelector({
				instance: me.instance,
				baseconfig: me,
				sheetoption: me.sheetoption,
				formulas: formulas,
				uitem: uitem,
				pselect: rec,
				callback: new IG$.callBackObj(me, function(sel) {
					var i,
						me = this,
						f = formulas;
					
					for (i=f.length-1; i>=0; i--)
					{
						if (f[i].baseuid == uitem.uid)
						{
							f.splice(i, 1);
						}
					}
					
					for (i=0; i < sel.length; i++)
					{
						f.push(sel[i]);
					}
					
					me.down("[name=grd_formula]").store.loadData(sel);
				})
			});
		}
		
		IG$.checkLogin(me, dlg);
	},
	
	initComponent : function() {
		var me=this,
			pitem = me.item,
			itemtype = (pitem) ? pitem.itemtype : null;

		// ig$.$l_ = ig$.$l_ || 0;
		
		$s.apply(this, {
			title: IRm$.r1("T_METRIC_SETTING"),
			padding: ig$.padding,
			items: [
				{
					xtype: "panel",
					layout: "anchor",
					autoScroll: true,
					defaults: {
						anchor: "100%"
					},
		
					items: [
						{
							xtype: "fieldset",
							title: IRm$.r1("L_SORT_SEL"),
							layout: "anchor",
							defaults: {
								anchor: "100%"
							},
							disabled: me.loc == "mea" ? true : false,
							items: [
								{
									xtype: "radiogroup",
									name: "optsortdir",
									fieldLabel: IRm$.r1("L_SORT_ORD"),
									plain: true,
									items: [
										{boxLabel: IRm$.r1("B_DEFAULT"), name: "cb_sortdir", inputValue: "", checked: true},
										{boxLabel: IRm$.r1("B_ASC"), name: "cb_sortdir", inputValue: "asc"},
										{boxLabel: IRm$.r1("B_DSC"), name: "cb_sortdir", inputValue: "desc"}
									]
								},
								{
									xtype: "radiogroup",
									name: "optsorttype",
									fieldLabel: IRm$.r1("L_SORT_TP"),
									plain: true,
									items: [
										{boxLabel: IRm$.r1("B_DEFAULT"), name: "cb_sorttype", inputValue: "", checked: true},
										{boxLabel: IRm$.r1("B_STRING"), name: "cb_sorttype", inputValue: "VARCHAR"},
										{boxLabel: IRm$.r1("B_NUMERIC"), name: "cb_sorttype", inputValue: "NUMBER"}
									]
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_OTHER_OPTION"),
							layout: "anchor",
							$w: 400,
							defaults: {
								anchor: "100%",
								$w: 400
							},
							items: [
								{
									xtype: "textfield",
									name: "disp_title",
									fieldLabel: IRm$.r1("L_DISP_TITLE")
								},
								{
									xtype: "checkbox",
									name: "hidecolumn",
									fieldLabel: IRm$.r1("L_COL_VIS"),
									boxLabel: IRm$.r1("B_HIDE")
								},
								{
									xtype: "textfield",
									name: "timeformat",
									fieldLabel: IRm$.r1("L_TIME_FMT")
								},
								{
									xtype: "displayfield",
									value: IRm$.r1("L_TIME_FMT_DSC")
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_AGGR"),
							layout: "anchor",
							hidden: me.item.type == "Metric" && me.loc == "mea" ? false : true,
							defaults: {
								anchor: "100%"
							},
							items: [
								{
									xtype: "combobox",
									name: "aggrfunc",
									fieldLabel: IRm$.r1("L_FUNC"),
									displayField: "name",
									valueField: "value",
									queryMode: "local",
									editable: false,
									store: {
										xtype: "store",
										fields: [
											"name", "value"
										],
										data: [
											{name: "Not Use", value: ""},
											{name: "Sum values", value: "SUM"},
											{name: "Count rows", value: "COUNT"},
											{name: "Distinct count", value: "COUNT_DISTINCT"},
											{name: "Minimum", value: "MIN"},
											{name: "Maximum", value: "MAX"},
											{name: "Average", value: "AVG"}
										]
									}
								}
							]
						},
						{
							xtype: "fieldset",
							title: IRm$.r1("L_FORMULA"),
							layout: "fit",
							height: 160,
							items: [
								{
									xtype: "gridpanel",
									
									border: 0,
									name: "grd_formula",
									bbar: [
										// "->",
										{
											text: IRm$.r1("L_CONFIG_FORMULA"),
											handler: function() {
												this.editFormula();
											},
											scope: this
										}	
									],
									store: {
										xtype: "store",
										fields: [
											"title", "expression", "baseuid", "fid"
										]
									},
									// selType: "checkboxmodel",
									columns: [
										{
											text: IRm$.r1("B_NAME"),
											flex: 1,
											dataIndex: "title"
										},
										{
											text: IRm$.r1("L_EXPRESSION"),
											flex: 1,
											dataIndex: "expression"
										},
										{
											xtype: "actioncolumn",
											width: 50,
											items: [
												{
													iconCls: "icon-grid-config",
													tooltip: IRm$.r1("L_EDIT"),
													handler: function (grid, rowIndex, colIndex) {
														var store = grid.store,
															rec = store.getAt(rowIndex);
														this.editFormula(rec);
													},
													scope: this
												},
												{
													iconCls: "icon-grid-delete",
													tooltip: "Delete item",
													handler: function (grid, rowIndex, colIndex) {
														var store = grid.store,
															rec = store.getAt(rowIndex),
															formulas = me.sheetoption.model.sheet_formula,
															i, buid = rec.get("baseuid"),
															fid = rec.get("fid");
															
														store.removeAt(rowIndex);
														
														for (i=0; i < formulas.length; i++)
														{
															if (formulas[i].baseuid == buid && formulas[i].fid == fid)
															{
																formulas.splice(i, 1);
																break;
															}
														}
													}
												}
											]
										}
									]
								}
							]
						}
					]
				}
			],
			buttons: [
				"->",
				{
					text: IRm$.r1("B_CONFIRM"),
					bodyCls: "ig-btn-confirm",
					handler: function() {
						this._confirm();
					},
					scope: this
				}, 
				{
					text: IRm$.r1("B_CANCEL"),
					handler:function() {
						this.close();
					},
					scope: this
				}
			],
			listeners: {
				afterrender: function() {
					this.init_f();
				}
			}
		});	
		
		IG$.dlgCellConfig.superclass.initComponent.apply(this, arguments);
	}
});
