

/**
 * checkbox control
 */
IG$._FC_checkbox = $s.extend(IG$._baseFC, {
	objtype: "checkbox",
	s_codemap: 1,
	s_metric: 1,
	md: 0,
	events: [
		{name: "change_val"}
	],
	create: function(container) {
		var me = this,
			fmodel = me.fmodel,
			fitem = me.fitem,
			showpopup = fmodel.showpopup,
			ui,
			fid = me._get_id();
			
		if (showpopup)
		{
			ui = $("<div class='idv-sel-combo'></div>")
				.appendTo(container);

			var sinp = $("<div class='idv-sel-flow-full'></div>")
				.appendTo(ui);
			var tin = $("<input type='text' class='idv-checkbox-inp'></input>").appendTo(sinp);
			var tbtn = $("<div class='idv-btn-selected'></div>").appendTo(ui);
			tbtn.bind("click", function(e) {
				e.stopPropagation();
				
				let hfilter = me.form.checkHFilter(fitem);
				
				if (hfilter == false)
					return;
				
				var dlg = new IG$.dynFilter({
					instance: me.instance,
					selModel: {
						mode: "MULTI",
						selType: "checkboxmodel",
						checkSelector: ".x-grid-cell"
					},
					smode: fitem.smode,
					callback: new IG$.callBackObj(me, me.rs_checkPopup, fitem),
					filteritem: fitem,
					hfilter: hfilter
				});
				IG$.checkLogin(this, dlg);
			});
		}
		else
		{
			ui = $("<select multiple='multiple'></select>")
				.css({height: 80})
				.appendTo(container);

			if (me.md)
			{
				container.addClass("form-outline");
				ui.addClass("form-control");

				lbl$ = me.lbl$ = $("<label class='form-label' for='" + fid + "'></label>").appendTo(container);
				$("<div class='form-helper'></div>").appendTo(container);
				// me.mp$ = new mdb.Input(container[0]);
				// me.mp$.init();
			}

			ui.bind("change", function() {
				me.trigger("change_val", fitem.updateValues == true);
			});
		}
		
		return ui;
	},
	setValue: function(values, cmap, svalues) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			ui = me.ui;
			
		if (fmodel.showpopup)
		{
			me.rs_checkPopup(svalues, fitem, false);
		}
		else
		{
			ui.val(values);
		}
	},
	updateValue: function(value) {
		var me = this,
			fitem = me.fitem,
			fmodel = me.fmodel,
			ui = me.ui,
			sval;
			
		if (fmodel.showpopup)
		{
			let selection = fitem.selection = fitem.selection || [];
			for (let j=0; j < selection.length; j++)
			{
				value.push({code: selection[j].code, value: selection[j].value});
			}
		}
		else
		{
			sval = ui.val() || [];
			for (let j=0; j < sval.length; j++)
			{
				if (sval[j] != "")
				{
					value.push({code: sval[j], value: sval[j]});
				}
			}
		}
	},
	loadData: function(data) {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			fitem = me.fitem,
			_init_value = fmodel._init_value || fmodel.initial_values;
			
		if (fmodel.objtype == "checkbox" && fmodel.showpopup)
		{
			fitem.selection = [];
			
			// hfilter = me.form.checkHFilter(fitem);
			
			if (_init_value)
			{
				me.rs_checkPopup(_init_value, fitem, false);
			}
		}
		else
		{
			ui.empty();
						
			dp = ui.attr("options");
			if (fmodel.showallvalue)
			{
				if (fmodel.isnecessary)
				{
					aname = fmodel.aname || IRm$.r1("L_SELECT_VALUE");
				}
				else
				{
					aname = fmodel.aname || IRm$.r1("L_ALL_VALUE");
				}
				$("<option value=''>" + aname + "</option>").appendTo(ui);
			}
			for(let i=0; i < data.length; i++)
			{
				// dp[i+1] = new Option(disp && disp.length > i ? disp[i] : data[i], data[i]);
				$("<option value='" + data[i].code + "'>" + (data[i].disp || data[i].code) + "</option>").appendTo(ui);
			}
			
			ui.trigger("change");
		}
	},
	clear: function() {
		var me = this,
			fmodel = me.fmodel,
			ui = me.ui,
			fitem = me.fitem,
			showpopup = fmodel.showpopup;
		if (showpopup)
		{
			$("input[type=text]", ui).val("");
			fitem.selection = [];
		}
		else
		{
			$("option:selected", ui).removeAttr("selected");
		}
	}
});

IG$.$FCinst["checkbox"] = new IG$._FC_checkbox();