	doSearch: function(kval, isopt) {
		var me = this,
			kword = me.down("[name=kword]"),
			pl2 = me.down("[name=pl2]"),
			b_csch = me.down("[name=b_csch]"),
			keyword = kword.getValue(),
			req = new IG$._rpc$(),
			searchOption = me.searchOption,
			soption;
		
		if (isopt)
		{
			kval = searchOption.keyword;
		}
		
		if (kval)
		{
			kword.setValue(kval);
			keyword = kval;
		}

		kword.clearInvalid();
		
		if (me.vmode == "tree")
		{
			pl2.getLayout().setActiveItem(kval || isopt ? 1 : 0);
			b_csch.setVisible(kval);
		}
		
		if (keyword || searchOption.fltsetdate == true)
		{
			soption = {option: "search", name: keyword};
			
			if (searchOption.fltsetdate)
			{
				soption.fromdate = searchOption.fltfromdate;
				soption.todate = searchOption.flttodate;
			}
			
			if (searchOption.typelist && searchOption.typelist.length > 0)
			{
				soption.typelist = searchOption.typelist.join(";");
			}
			
			me.load_content(6, null, soption);
		}
		else
		{
			kword.markInvalid("Required!");
		}
	},
	
	showSearchOption: function() {
		var me = this,
			kword = me.down("[name=kword]"),
			dlg;
		
		me.searchOption.keyword = kword.getValue();
		
		dlg = new IG$.explorerSearch({
			instance: me.instance,
			searchOption: me.searchOption,
			callback: new IG$.callBackObj(this, function() {
				this.doSearch(null, true);
			})
		});
		
		IG$.checkLogin(this, dlg);
	},
	
