	_update_detail: function() {
		var me = this,
			_grid_sel = me._grid_sel,
			grd_rev_hist = me.down("[name=grd_rev_hist]");
		
		me.down("[name=d_name]").clearInvalid();
		
		$.each(["name", "description", "nodepath", "owner", "modifier", "updatedatefm"], function(i, k) {
			var ctrl = me.down("[name=d_" + k + "]");
			if (!_grid_sel)
			{
				ctrl.setValue("");
			}
			else
			{
				ctrl.setValue(_grid_sel.get(k));
			}
		});
		
		if (_grid_sel)
		{
			me.loadRelation(_grid_sel.get("uid"), "grd_rel_sub");
			
			me.loadRevision(_grid_sel.get("uid"), _grid_sel.get("revision"), grd_rev_hist);
		}
		else
		{
			me.down("[name=grd_rel_sub]").store.loadData([]);
			grd_rev_hist.store.loadData([]);
		}
	},
	
	_save_detail_item: function() {
		var me = this,
			_grid_sel = me._grid_sel;
		
		if (_grid_sel)
		{
			var req = new IG$._rpc$(),
				cname = me.down("[name=d_name]"),
				cdesc = me.down("[name=d_description]");
			
			cname.clearInvalid();
			
			if (!cname.getValue())
			{
				cname.markInvalid("Required!");
				return;
			}
			
			req.init(me, 
				{
					ack: "writecontent",
					payload: {uid: _grid_sel.get("uid"), name: cname.getValue(), description: cdesc.getValue()},
					mbody: {option: "rename"}
				}, me, function(jdoc) {
					_grid_sel.set("name", cname.getValue());
					_grid_sel.set("description", cdesc.getValue());
					_grid_sel.set("locale_name", cname.getValue());
					
					IG$.alertmsg(ig$.appname, IRm$.r1("M_SAVED"), null, me, 0, "success");
				}, false
			);
			req.send();
		}
	},
	
	loadRelation: function(uid, grd) {
		var me = this,
			lreq = new IG$._rpc$(),
			isdown = me.down("[name=cb_rel_isdown]").getGroupValue();
		
		lreq.init(me, 
			{
				ack: "helpcontent",
				payload: {uid: uid || me.uid},
				mbody: {option: "relations", isdown: isdown, detail: "info"}
			}, me, function(jdoc) {
				var me = this,
					grd_rel = me.down("[name=" + (grd || "grd_rel") + "]"),
					tnodes = jdoc && jdoc.children ? jdoc.children : [],
					i, d, dm,
					txtrel = me.down("[name=txtrel]"),
					dp = [];
				
				if (!uid)
				{
					txtrel.setValue("Relations : " + jdoc.name + "(" + jdoc.nodepath + ")");
				}
				for (i=0; i < tnodes.length; i++)
				{
					d = tnodes[i];
					d.iconcls = IG$.get_metatype_icon(d.type.toLowerCase(), d);
					dp.push(d);
				}
				
				grd_rel.store.loadData(dp);
			}, false);
			
		lreq.send();
	},
	
	loadRevision: function(uid, revision, grid) {
		var me = this,
			req = new IG$._rpc$();
		
		req.init(me, 
			{
				ack: "revision",
				payload: {uid: uid},
				mbody: {option: 'get'}
			}, me, function(jdoc) {
				var tnode = jdoc.revisions,
					d, dt = [],
					i;
				
				if (tnode)
				{
					for (i=0; i < tnode.length; i++)
					{
						d = tnode[i];
						d.uid = uid;
						d.iscurrent = (revision == d.revision) ? "YES" : "";
						dt.push(d);
					}
				}
				grid.store.loadData(dt);
			}, false
		);
		req.send();
	},
	
